function collectionProgressHTML(){const job=latest('collection');if(!job)return `<section class="panel collection-progress-panel"><div class="panel-head"><h2>${icon('database')} ${translateStatic('수집 진행')}</h2>${badge('Idle')}</div><div class="collection-progress-empty">${translateStatic('수집을 시작하면 실제 저장 샘플 수와 진행률을 표시합니다.')}</div></section>`;const current=job.progress_current,total=job.progress_total,pct=finite(job.progress_pct)?job.progress_pct:finite(current)&&finite(total)&&total>0?current/total*100:null;return `<section class="panel collection-progress-panel"><div class="panel-head"><div><h2>${icon('database')} ${job.status==='Running'?translateStatic('현재 수집 진행'):translateStatic('최근 수집 진행')}</h2><p>${esc(job.name||job.id)}</p></div>${badge(job.status)}</div><div class="collection-progress-body"><div class="collection-progress-count"><div><span>${translateStatic('저장된 샘플')}</span><strong>${num(current)} <small>/ ${num(total)}</small></strong></div><div class="collection-progress-percent">${finite(pct)?`${num(pct,1)}<small>%</small>`:'—'}</div></div><div class="track" ${finite(pct)?`role="progressbar" aria-label="${translateStatic('샘플 수집 진행')}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.max(0,Math.min(100,pct))}"`:''}><span style="width:${finite(pct)?Math.max(0,Math.min(100,pct)):0}%"></span></div><div class="collection-progress-bottom"><div><span>${translateStatic('경과')} ${elapsed(job)}</span>${job.last_event?.town?`<span>${translateStatic('수집 타운')} ${esc(job.last_event.town)}${finite(job.last_event.town_saved)&&finite(job.last_event.town_target)?` · ${num(job.last_event.town_saved)} / ${num(job.last_event.town_target)}`:''}</span>`:''}<p class="job-message">${esc(job.message||translateStatic('작업 상태를 확인하고 있습니다.'))}</p></div><div class="inline-actions">${button(translateStatic('작업 로그'),'job-logs','subtle small','terminal',`data-id="${esc(job.id)}"`)}${job.status==='Running'?button(job.stop_requested?translateStatic('종료 처리 중'):translateStatic('수집 중지'),'stop-job','danger small','stop',`data-id="${esc(job.id)}" ${job.stop_requested?'disabled':''}`):''}</div></div></div></section>`;}
