const field=(name,label,value,{type='text',min,max,step,unit='',hint='',options,readonly=false,cls='',required=false}={})=>`<div class="field ${cls}"><label for="${esc(name)}">${label}${unit?`<span class="unit">${unit}</span>`:''}</label>${options?`<select id="${esc(name)}" name="${esc(name)}" ${readonly?'disabled':''}>${options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`;}).join('')}</select>`:`<input id="${esc(name)}" name="${esc(name)}" value="${esc(value)}" type="${type}" ${min!==undefined?`min="${min}"`:''} ${max!==undefined?`max="${max}"`:''} ${step!==undefined?`step="${step}"`:''} ${readonly?'readonly':''} ${required?'required':''}>`}${hint?`<small>${hint}</small>`:''}</div>`;
