function toast(message,error=false){const el=document.createElement('div');el.className=`toast${error?' error':''}`;el.innerHTML=ui`${icon(error?'alert':'check')}<span>${esc(message)}</span><button aria-label="알림 닫기">${icon('close')}</button>`;el.querySelector('button').onclick=()=>el.remove();document.querySelector('#toasts').append(el);setTimeout(()=>el.remove(),error?12000:5500);}
let authPromise=null;
const authToken=()=>sessionStorage.getItem('sdv-auth-token')||'';
async function requestToken(){if(authPromise)return authPromise;authPromise=(async()=>{const dlg=document.querySelector('#confirm-dialog');if(dlg.open)dlg.close('cancel');document.querySelector('#dialog-title').textContent=translateStatic('접속 키가 필요합니다');document.querySelector('#dialog-message').textContent=translateStatic('서버에 설정한 SDV_AUTH_TOKEN을 입력하세요. 키는 이 브라우저 탭의 세션 동안만 저장됩니다.');document.querySelector('.dialog-icon').innerHTML=icon('shield');document.querySelector('#dialog-detail').innerHTML=translateStatic('<div class="field" style="padding:15px 0"><label for="auth-token-input">서버 접속 키</label><input type="password" id="auth-token-input" autocomplete="off" spellcheck="false" placeholder="SDV_AUTH_TOKEN"></div>');const btn=document.querySelector('#dialog-confirm');btn.textContent=translateStatic('연결');btn.className='button primary';dlg.returnValue='';dlg.showModal();document.querySelector('#auth-token-input').focus();const result=await new Promise(resolve=>dlg.addEventListener('close',()=>resolve(dlg.returnValue==='confirm'?document.querySelector('#auth-token-input')?.value.trim():null),{once:true}));document.querySelector('#dialog-detail').innerHTML='';if(result)sessionStorage.setItem('sdv-auth-token',result);return result;})();try{return await authPromise;}finally{authPromise=null;}}
async function authenticatedFetch(path,options={},retry=true){const token=authToken();const res=await fetch(path,{...options,headers:{...options.headers,...(token?{Authorization:`Bearer ${token}`}:{})}});if(res.status===401&&retry){sessionStorage.removeItem('sdv-auth-token');if(await requestToken())return authenticatedFetch(path,options,false);}return res;}
async function api(path,method='GET',body,options={}){const res=await authenticatedFetch(path,{...options,method,headers:{...(method!=='GET'?{'X-SDV-Request':'1'}:{}),...(body!==undefined?{'Content-Type':'application/json'}:{})},body:body===undefined?undefined:JSON.stringify(body)});let data;try{data=await res.json();}catch{throw new Error(ui`서버 응답을 읽을 수 없습니다 (${res.status}).`);}if(!res.ok){const original=typeof data.detail==='string'?data.detail:JSON.stringify(data.detail||data);throw new Error(language==='en'?`Server message (original): ${original}`:original);}return data;}
async function imageSource(img,url,options={}){const signal=options.signal;const res=await authenticatedFetch(url,{signal,cache:'no-store'});if(!res.ok){img.dispatchEvent(new Event('error'));return;}const blob=await res.blob();if(signal?.aborted)throw new DOMException('Image request aborted','AbortError');const objectURL=URL.createObjectURL(blob);let released=false;const release=()=>{if(released)return;released=true;URL.revokeObjectURL(objectURL);img.removeEventListener('load',release);img.removeEventListener('error',release);signal?.removeEventListener('abort',abort);};const abort=()=>{if(img.src===objectURL)img.removeAttribute('src');release();};img.addEventListener('load',release,{once:true});img.addEventListener('error',release,{once:true});signal?.addEventListener('abort',abort,{once:true});if(signal?.aborted){release();throw new DOMException('Image request aborted','AbortError');}img.src=objectURL;}

async function confirmAction(title,message,label=translateStatic('시작'),detail='',danger=false){const dlg=document.querySelector('#confirm-dialog');document.querySelector('#dialog-title').textContent=title;document.querySelector('#dialog-message').textContent=message;document.querySelector('#dialog-detail').innerHTML=detail;document.querySelector('.dialog-icon').innerHTML=icon(danger?'stop':'play');const b=document.querySelector('#dialog-confirm');b.textContent=label;b.className=`button ${danger?'danger':'primary'}`;b.disabled=false;dlg.returnValue='';dlg.showModal();return new Promise(resolve=>dlg.addEventListener('close',()=>resolve(dlg.returnValue==='confirm'),{once:true}));}
function adopt(data){const previousLocalTask=state.carla_local?.task,wasLocalReady=state.carla_local?.engine?.ready===true,wasCarlaConnected=state.carla.connected===true,wasPreviewBusy=previewBusy(),previousPretrained=state.pretrained;for(const key of ['settings','sensors','training','capabilities','carla','carla_local','sensor_preview','resources','training_options','pretrained','model_catalog','metric_registry'])if(data[key])state[key]=data[key];for(const key of ['jobs','experiments','datasets','queue'])if(data[key])state[key]=arr(data[key],key);state.online=true;state.lastUpdate=new Date();if(data.training_options)trainingOptionsContext=trainingOptionsKey({sensor_use:Object.fromEntries(trainingSensorIds.map(key=>[key,Boolean(state.training.sensor_use?.[key])])),train_data:state.settings.train_data,val_data:state.settings.val_data,...(state.training.task_settings?{task_settings:state.training.task_settings}:{})});if(data.pretrained&&document.querySelector('#main')&&Object.entries(state.pretrained.models||{}).some(([key,value])=>key===selectedEncoder()&&value.ready&&!previousPretrained?.models?.[key]?.ready))checkPreflight('training',true,false);if(data.carla_local){state.localError='';const task=state.carla_local.task;if(task?.operation==='prepare'&&task.id&&['Completed','Failed','Stopped'].includes(task.status)&&(previousLocalTask?.id!==task.id||previousLocalTask?.status!==task.status)&&!data.capabilities)refreshCapabilitiesAfterCarla(task);}if(((!wasLocalReady&&state.carla_local?.engine?.ready===true)||(!wasCarlaConnected&&state.carla.connected===true))&&document.querySelector('#main'))checkPreflight('collection',true);if(wasPreviewBusy&&!previewBusy()&&document.querySelector('#main')){checkPreflight('collection',true);checkPreflight('training',true);}}
const localCapabilityRefreshes=new Set();
async function refreshCapabilitiesAfterCarla(task){const key=`${task.id}:${task.status}`;if(localCapabilityRefreshes.has(key))return;localCapabilityRefreshes.add(key);try{const data=await api('/api/bootstrap');applyEnvironment(data);await checkPreflight('collection',true);}catch(error){toast(ui`CARLA 작업 후 환경 정보를 갱신하지 못했습니다. 환경 종속성에서 다시 검사하세요. ${error.message}`,true);}}
function shell(){document.querySelector('#app').innerHTML=ui`<div class="app-shell"><aside class="sidebar" id="sidebar"><a class="brand" href="#dashboard" aria-label="SDV Studio 대시보드"><div class="brand-symbol">${icon('road')}</div><div class="brand-text"><strong>SDV Studio</strong><small>Self-driving validation</small></div></a><div class="nav-section">연구 워크스페이스</div><nav aria-label="메인 메뉴">${Object.entries(routes).map(([key,r])=>`<a class="nav-link" href="#${key}" data-route="${key}" title="${r.title}">${icon(key)}<span>${({dashboard:translateStatic('대시보드'),simulation:translateStatic('시뮬레이션 · 수집'),training:translateStatic('모델 학습'),results:translateStatic('실험 결과'),settings:translateStatic('시스템 설정')})[key]}</span></a>`).join('')}</nav><div class="sidebar-spacer"></div><div class="sidebar-note"><div class="note-title">${icon('shield')}로컬 연구 환경</div><p>작업은 서버에서 계속 실행됩니다.<br>브라우저를 닫아도 기록이 유지됩니다.</p></div><div class="sidebar-bottom"><span>SDV Studio</span><span>Web workspace</span></div></aside><div class="overlay" data-action="menu"></div><header class="topbar"><div class="breadcrumb"><button class="icon-button mobile-menu" aria-label="메뉴 열기" data-action="menu">${icon('menu')}</button><span id="project-label"></span>${icon('chevron')}<strong id="route-label"></strong></div><div class="top-tools"><label style="display:inline-flex;align-items:center;gap:5px" title="${translateStatic('언어')}"><select id="ui-language" aria-label="${translateStatic('언어')}" style="height:31px;width:62px;border:1px solid var(--line);border-radius:6px;background:var(--surface);color:var(--text);font-size:11px;padding:4px 7px"><option value="ko" ${language==='ko'?'selected':''}>KO</option><option value="en" ${language==='en'?'selected':''}>EN</option></select></label><span class="top-status server-label">${icon('server')}<span id="host-label"></span></span><span class="top-divider"></span><span class="top-status" id="connection-label"></span><button class="icon-button" data-action="refresh" title="상태 새로고침" aria-label="상태 새로고침">${icon('refresh')}</button></div></header><main class="main" id="main" tabindex="-1"></main></div>`;}
function workflow(){const done=[Boolean(state.settings.project_name),state.datasets.some(d=>d.samples>0),state.experiments.length>0,false];return ui`<nav class="workflow" aria-label="연구 진행 단계">${[['settings',translateStatic('환경 설정'),translateStatic('연결과 저장 경로')],['simulation',translateStatic('데이터 수집'),translateStatic('시뮬레이션 · 센서')],['training',translateStatic('모델 학습'),translateStatic('모델 · 학습 파라미터')],['results',translateStatic('결과 분석'),translateStatic('성능 비교 · 내보내기')]].map(([key,label,sub],i)=>`<a href="#${key}" class="flow-step ${state.route===key?'current':''} ${done[i]?'done':''}"><span class="flow-number">${done[i]?icon('check'):i+1}</span><span><span class="flow-label">${label}</span><small>${sub}</small></span>${icon('chevron','flow-chevron')}</a>`).join('')}</nav>`;}
function heading(){let actions='';if(state.route==='dashboard')actions=ui`<a class="button subtle" href="#settings">${icon('settings')}환경 설정</a><a class="button primary" href="#simulation">${icon('play')}데이터 수집 준비</a>`;if(state.route==='results')actions=button(translateStatic('목록 새로고침'),'refresh-catalog','subtle','refresh');if(state.route==='settings')actions=`${button(translateStatic('설정 내보내기'),'export-settings','subtle','download')}${button(translateStatic('설정 불러오기'),'import-settings','subtle','upload')}<input type="file" id="settings-file" accept="application/json,.json" hidden>`;return `<div class="page-heading"><div><h1>${routes[state.route].title}</h1><p>${routes[state.route].description}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`;}
let languageResume=null;try{languageResume=JSON.parse(sessionStorage.getItem('sdv-language-draft')||'null');sessionStorage.removeItem('sdv-language-draft');}catch{}
const drafts=languageResume?.drafts||{};
if(languageResume){for(const key of ['simTab','trainTab','livePreview','previewId','previewChannel','trainMetric','metric','collectionDirty','trainingDirty','bevDecoderChoice','taskDraftSettings'])if(key in languageResume)state[key]=languageResume[key];state.selected=new Set(languageResume.selected||[]);}
function switchUILanguage(value){if(value===language)return;captureDrafts();const resume={drafts,selected:[...state.selected],scrollY:window.scrollY,previewSensor:document.querySelector('#sp-sensor')?.value,previewView:document.querySelector('#sp-view')?.value,datasetSplits:Object.fromEntries([...document.querySelectorAll('[data-dataset-split]')].map(el=>[el.dataset.datasetSplit,el.value]))};for(const key of ['simTab','trainTab','livePreview','previewId','previewChannel','trainMetric','metric','collectionDirty','trainingDirty','bevDecoderChoice','taskDraftSettings'])resume[key]=state[key];try{sessionStorage.setItem('sdv-language-draft',JSON.stringify(resume));setLanguage(value);location.reload();}catch(error){try{sessionStorage.removeItem('sdv-language-draft');}catch{}const selector=document.querySelector('#ui-language');if(selector)selector.value=language;toast(translateStatic('언어 설정을 저장할 수 없습니다. 브라우저 저장소 설정을 확인하세요.'),true);}}
function restoreLanguageView(){if(!languageResume)return;document.querySelectorAll('[data-dataset-split]').forEach(el=>{const value=languageResume.datasetSplits?.[el.dataset.datasetSplit];if(value!==undefined)el.value=value;});for(const [selector,key] of [['#sp-sensor','previewSensor'],['#sp-view','previewView']]){const el=document.querySelector(selector),value=languageResume[key];if(el&&value&&el.value!==value){el.value=value;el.dispatchEvent(new Event('change',{bubbles:true}));}}const scrollY=languageResume.scrollY||0;languageResume=null;requestAnimationFrame(()=>window.scrollTo(0,scrollY));}
function captureDrafts(){document.querySelectorAll('#main form[id]').forEach(form=>{drafts[form.id]={};form.querySelectorAll('[name]').forEach(el=>{if(el.type!=='file')drafts[form.id][el.name]={value:el.value,checked:el.checked};});});}
function restoreDrafts(){for(const [id,values] of Object.entries(drafts)){const form=document.getElementById(id);if(!form)continue;form.querySelectorAll('[name]').forEach(el=>{const d=values[el.name];if(!d)return;if(el.type==='checkbox')el.checked=d.checked;else el.value=d.value;});}}
function render(){if(!document.querySelector('#main')||!document.querySelector('#sidebar'))return;unmountDriving();unmountSequence();stopGalleryTimelines();predictionImageObserver?.disconnect();captureDrafts();applyRoute();document.title=`${routes[state.route].title} · SDV Studio`;document.querySelectorAll('[data-route]').forEach(a=>{const selected=a.dataset.route===state.route;a.classList.toggle('active',selected);selected?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current');});document.querySelector('#sidebar').classList.remove('is-open');document.querySelector('#main').innerHTML=ui`${heading()}${workflow()}<div id="offline-banner"></div>${({dashboard:dashboard,simulation:simulation,training:training,results:results,settings:settings})[state.route]()}<footer class="page-footer"><span>SDV Studio · 자율주행 AI 연구 워크스페이스</span><span id="updated-at">실제 서버 상태와 저장된 실험 기록을 표시합니다.</span></footer>`;restoreDrafts();mountDriving({api,state});if(state.route==='training'&&state.trainTab==='setup'){syncBEVDecoder();refreshTrainingOptions();}window.SensorPreview?.mount({state,api,imageSource,confirm:confirmAction});mountPipelinePage();updateTop();renderLive();if(state.route==='training'&&state.trainTab==='monitor')loadLogs();if(state.route==='training'&&state.trainTab==='queue')refreshQueue();if(state.route==='simulation'&&state.simTab==='collect')loadLogs('collection');if(state.route==='results'&&state.detail)renderDetail();}
function updateTop(){if(!document.querySelector('#project-label'))return;document.querySelector('#project-label').textContent=state.settings.project_name||'SDV Research';document.querySelector('#route-label').textContent=language==='ko'?routes[state.route].title:routes[state.route].en;document.querySelector('#host-label').textContent=`${state.settings.carla_host||'—'}:${state.settings.carla_port||'—'}`;const connection=document.querySelector('#connection-label'),connectionText=state.online?translateStatic('상태 동기화 중'):translateStatic('서버 연결 끊김');connection.innerHTML=`<span class="dot ${state.online?'green':'amber'}" aria-hidden="true"></span><span class="connection-text">${esc(connectionText)}</span>`;connection.title=connectionText;connection.setAttribute('aria-label',connectionText);connection.setAttribute('role','status');const banner=document.querySelector('#offline-banner');if(banner)banner.innerHTML=state.online?'':`<div class="system-warning">${alertBox(translateStatic('서버 연결이 끊겼습니다. 표시된 값은 마지막 수신 상태입니다. 서버 실행 상태를 확인한 뒤 새로고침하세요.'),'error')}</div>`;const last=document.querySelector('#updated-at');if(last&&state.lastUpdate)last.textContent=ui`마지막 수신 ${state.lastUpdate.toLocaleTimeString(locale,{hour12:false})}`;}
function dashboard(){return ui`<div class="stats-grid" id="dashboard-stats"></div><div class="grid main-aside"><div class="stack"><section class="panel"><div class="panel-head"><h2>현재 실행 작업</h2><span id="current-badge">${badge('Idle')}</span></div><div id="current-operation"></div><div class="panel-foot"><span>별도 작업 프로세스로 실행되어 화면 이동 중에도 유지됩니다.</span>${icon('activity')}</div></section>${panel(translateStatic('최근 실험'),`<div id="recent-experiments"></div>`,ui`<a href="#results" class="text-link">전체 보기 ${icon('arrow')}</a>`)}${panel(translateStatic('시스템 알림'),`<div id="system-notices"></div>`)}</div><div class="stack">${panel(translateStatic('다음 연구 단계'),`<div class="checklist" id="research-checklist"></div>`)}${panel(translateStatic('시스템 리소스'),`<div class="panel-body" id="resource-monitor"></div>`,ui`<span class="small faint">실측값</span>`)}</div></div>`;}
function dashboardStats(){const collect=latest('collection'),train=latest('training');const samples=state.datasets.filter(d=>d.kind==='collection').reduce((a,d)=>a+(n(d.samples)||0),0);return [{label:translateStatic('CARLA 서버'),value:state.carla.connected?translateStatic('연결됨'):translateStatic('연결 대기'),sub:state.carla.connected?state.carla.map||translateStatic('시뮬레이션 서버 연결됨'):`${state.settings.carla_host}:${state.settings.carla_port}`,symbol:'server',status:true},{label:translateStatic('수집 데이터'),value:num(samples),sub:collect?.status==='Running'?translateStatic('데이터 수집 실행 중'):ui`${num(state.datasets.filter(d=>d.kind==='collection').length)}개 수집 Scene`,symbol:'database'},{label:translateStatic('모델 학습'),value:({Running:translateStatic('학습 중'),Completed:translateStatic('완료'),Failed:translateStatic('실패'),Stopped:translateStatic('중지')})[train?.status]||translateStatic('대기 중'),sub:train?train.name:translateStatic('설정 저장 후 학습을 시작하세요'),symbol:'training',status:true},{label:translateStatic('저장된 실험'),value:num(state.experiments.length),sub:translateStatic('결과 파일에서 확인한 실험'),symbol:'results'}].map(s=>`<article class="stat"><div class="stat-top"><span>${s.label}</span>${icon(s.symbol)}</div><div class="stat-value ${s.status?'status-text':''}">${esc(s.value)}</div><div class="stat-sub">${s.label===translateStatic('CARLA 서버')?`<span class="dot ${state.carla.connected?'green':'amber'}"></span>`:''}${esc(s.sub)}</div></article>`).join('');}
function resourceHTML(){const r=state.resources;const cpu=r.cpu_percent??r.cpu?.percent;const memory=r.memory||{};const mem=r.memory_percent??memory.percent;const gpu=Array.isArray(r.gpus)?r.gpus[0]:r.gpu;const gp=gpu?.utilization??gpu?.utilization_gpu??gpu?.utilization_percent??gpu?.utilization_pct;const rows=[[translateStatic('CPU 사용량'),cpu,finite(cpu)?`${num(cpu,1)}%`:translateStatic('측정 불가'),'',r.cpu_count?ui`${r.cpu_count}개 논리 코어`:''],[translateStatic('메모리'),mem,finite(mem)?`${num(mem,1)}%`:translateStatic('측정 불가'),'blue',memory.used!==undefined?`${bytes(memory.used)} / ${bytes(memory.total)}`:finite(r.memory_used_gb)?`${num(r.memory_used_gb,1)} / ${num(r.memory_total_gb,1)} GB`:''],[translateStatic('GPU 사용량'),gp,finite(gp)?`${num(gp,1)}%`:translateStatic('측정 불가'),'muted',gpu?.name?`${gpu.name}${finite(gpu.memory_used_mb)?ui` · 메모리 ${num(gpu.memory_used_mb/1024,1)} / ${num(gpu.memory_total_mb/1024,1)} GB`:''}`:r.gpu_error||translateStatic('사용 가능한 GPU 측정 정보가 없습니다.')]];return rows.map(([label,value,text,cls,hint])=>`<div class="resource-row"><div class="resource-label"><span>${label}</span><strong>${text}</strong></div><div class="track ${cls}" ${finite(value)?`role="progressbar" aria-label="${label}" aria-valuenow="${Math.round(value)}" aria-valuemin="0" aria-valuemax="100"`:''}><span style="width:${finite(value)?Math.max(0,Math.min(100,value)):0}%"></span></div>${hint?`<div class="resource-note">${esc(hint)}</div>`:''}</div>`).join('');}
function operationHTML(job){if(!job&&previewBusy()){const preview=state.sensor_preview;return `<div class="operation-empty" data-preview-operation><div class="visual-mark">${icon('camera')}</div><div><h3>${previewStatusLabel()}</h3><p>${translateStatic('센서 프리뷰가 CARLA를 사용하고 있습니다. 수집·학습이나 연결·엔진 변경 전에 프리뷰를 중지하세요.')}</p>${preview.message?`<p class="job-message">${esc(preview.message)}</p>`:''}<a class="text-link" href="#simulation" data-action="open-sensor-preview">${translateStatic('센서 구성으로 이동')} ${icon('arrow')}</a></div></div>`;}if(!job)return ui`<div class="operation-empty"><div class="visual-mark">${icon('road')}</div><div><h3>새로운 실험을 준비하세요</h3><p>현재 실행 중인 작업이 없습니다.<br>CARLA 연결과 수집 설정을 확인해 연구를 시작하세요.</p><a class="text-link" href="#simulation">시뮬레이션 설정으로 이동 ${icon('arrow')}</a></div></div>`;return jobCard(job);}
function elapsed(job){if(!job?.started_at)return '—';const time=v=>new Date(typeof v==='number'?v*1000:v).getTime();const seconds=Math.max(0,Math.floor(((job.finished_at?time(job.finished_at):Date.now())-time(job.started_at))/1000));return seconds>=3600?ui`${Math.floor(seconds/3600)}시간 ${Math.floor(seconds%3600/60)}분`:seconds>=60?ui`${Math.floor(seconds/60)}분 ${seconds%60}초`:ui`${seconds}초`;}
function jobCard(job){const pct=job.progress_pct??(finite(job.progress_current)&&job.progress_total>0?job.progress_current/job.progress_total*100:null),eta=trainingETA(job);return ui`<div class="job-progress"><div class="job-name">${icon(job.kind==='training'?'training':'simulation')}<strong>${esc(job.name||job.id)}</strong>${badge(job.status)}</div><div class="progress-line"><span>${job.kind==='training'?translateStatic('Epoch 진행'):translateStatic('샘플 수집 진행')}</span><strong>${finite(pct)?`${num(pct,1)}<span class="small"> %</span>`:translateStatic('<span class="small">진행률 대기</span>')}</strong></div><div class="track"><span style="width:${finite(pct)?Math.min(100,Math.max(0,pct)):0}%"></span></div><div class="job-meta"><span>진행 ${num(job.progress_current)} / ${num(job.progress_total)}</span><span>경과 ${job.kind==='training'&&finite(job.active_elapsed_seconds)?duration(activeSeconds(job)):elapsed(job)}</span><span>PID ${esc(job.pid||'—')}</span></div>${job.kind==='training'?`<div class="job-eta"><span>${translateStatic('예상 남은 시간')} <strong>${eta?duration(eta.remaining):translateStatic('Epoch 측정 대기')}</strong></span>${eta?`<span>${translateStatic('예상 완료')} <strong>${stamp(eta.finish/1000)}</strong></span>`:''}<small>${translateStatic('완료된 Epoch의 실제 실행 시간을 기준으로 추정합니다.')}</small></div>`:''}<div class="job-message">${esc(job.message||translateStatic('작업 상태를 확인하고 있습니다.'))}</div>${job.status==='Pausing'?alertBox(translateStatic('현재 Epoch를 끝내고 모델·Optimizer·학습 진행 정보를 저장한 뒤 일시정지합니다.'),'info'):''}${job.kind==='training'&&job.last_event?.global_step!==undefined?`<div class="job-meta"><span>Global step ${num(job.last_event.global_step)}</span><span>Batch loss ${metricValue(job.last_event.metrics?.train_batch_loss)}</span></div>`:''}<div class="inline-actions spaced">${job.kind==='training'&&job.status==='Running'?button(translateStatic('일시정지'),'pause-job','subtle','clock',`data-id="${esc(job.id)}" ${job.pause_requested?'disabled':''}`):''}${stoppedTrainingActions(job)}${['Running','Pausing'].includes(job.status)?button(job.stop_requested?translateStatic('종료 처리 중'):translateStatic('작업 중지'),'stop-job','danger','stop',`data-id="${esc(job.id)}" ${job.stop_requested?'disabled':''}`):''}</div></div>`;}
function researchChecklist(){const checks=[[translateStatic('환경 설정'),translateStatic('CARLA 주소와 연구 데이터 저장 위치를 지정합니다.'),Boolean(state.settings.project_name),'settings',translateStatic('설정')],[translateStatic('CARLA 연결'),state.carla.connected?translateStatic('CARLA 서버에 연결되어 있습니다.'):translateStatic('서버를 실행한 뒤 연결 상태를 확인하세요.'),state.carla.connected,'simulation',translateStatic('연결')],[translateStatic('데이터 준비'),state.datasets.some(d=>d.kind==='train'&&d.samples>0)?translateStatic('학습 데이터가 준비되어 있습니다.'):translateStatic('수집 Scene을 학습 / 검증 데이터로 분할하세요.'),state.datasets.some(d=>d.kind==='train'&&d.samples>0),'simulation',translateStatic('준비')],[translateStatic('모델 학습'),translateStatic('학습 준비 검사를 통과하면 실험을 시작할 수 있습니다.'),state.preflight.training?.ready,'training',translateStatic('확인')]];return checks.map(([title,description,done,route,label],i)=>`<div class="check-row ${done?'':'unmet'}"><span class="check-circle ${done?'ok':''}">${done?icon('check'):i+1}</span><div class="check-content"><strong>${title}</strong><p>${esc(description)}</p></div><a href="#${route}" class="text-link">${label}</a></div>`).join('');}
function noticeHTML(){const local=state.carla_local,task=local?.task;if(task?.status==='Running')return `<div class="panel-body">${alertBox(ui`${esc(task.message||translateStatic('로컬 CARLA 설치·실행을 준비하고 있습니다.'))}${finite(task.progress_pct)?` (${num(task.progress_pct,1)}%)`:''}<br><a href="#simulation" data-action="open-local-carla" class="text-link">CARLA 설치·실행 진행 상황 ${icon('arrow')}</a>`,'info',translateStatic('로컬 CARLA 준비 중'))}</div>`;if(local?.error||task?.status==='Failed')return `<div class="panel-body">${alertBox(ui`${esc(local.error||task.message||translateStatic('CARLA 로그에서 실패 원인을 확인하세요.'))}<br><a href="#simulation" data-action="open-local-carla" class="text-link">CARLA 상태·로그 확인 ${icon('arrow')}</a>`,'error',translateStatic('로컬 CARLA 확인 필요'))}</div>`;const failed=state.jobs.find(j=>j.status==='Failed');if(failed)return `<div class="panel-body">${alertBox(esc(failed.message||translateStatic('작업 로그에서 실패 원인을 확인하세요.')),'error',esc(failed.name+translateStatic(' 실행 실패')))}</div>`;if(!state.carla.connected)return ui`<div class="empty-inline">${icon('info')}<div><strong>CARLA 서버 연결을 확인하세요</strong><p>시뮬레이션 서버를 실행한 후 데이터 수집 페이지에서 연결할 수 있습니다.<br>학습 결과 조회와 설정 편집은 연결 없이 사용할 수 있습니다.</p></div></div>`;return ui`<div class="empty-inline">${icon('check')}<div><strong>확인된 실행 오류가 없습니다</strong><p>작업 중 발생하는 오류와 종료 상태가 여기에 표시됩니다.</p></div></div>`;}
function experimentTable(list,selection=false){if(!list.length)return empty('results',translateStatic('아직 저장된 실험이 없습니다'),translateStatic('학습을 실행하면 결과 파일, 지표와 Checkpoint가 여기에 표시됩니다.'),ui`<a class="button subtle small" href="#training">학습 설정 확인</a>`);return ui`<div class="table-wrap"><table class="experiment-records"><thead><tr>${selection?translateStatic('<th scope="col">비교</th>'):''}<th scope="col">실험 이름</th><th scope="col">모델 / 태스크</th><th scope="col">Optimizer</th><th scope="col">LR / Batch</th><th scope="col">Epoch</th><th scope="col">Checkpoint</th><th scope="col">최근 수정</th><th scope="col">결과</th></tr></thead><tbody>${list.map(e=>{const c=experimentConfig(e),summary=e.summary||{};return ui`<tr>${selection?ui`<td><input aria-label="${esc(e.name)} 비교 선택" type="checkbox" data-compare="${esc(e.id)}" ${state.selected.has(e.id)?'checked':''}></td>`:''}<td><button class="table-link" data-action="experiment" data-id="${esc(e.id)}"><strong>${esc(e.name)}</strong><small>${esc(e.source||e.path||'')}</small></button></td><td><strong>${esc(e.encoder||summary.encoder||c.model?.encoder||'—')}</strong><small>${esc(e.tasks?.join?.(', ')||summary.tasks?.join?.(', ')||Object.keys(c.model_conf||{}).filter(k=>c.model_conf[k]).join(', ')||'—')}</small></td><td>${esc(e.optimizer||summary.optimizer||optimizerName(c))}</td><td>${esc(e.learning_rate??e.lr??summary.learning_rate??summary.lr??c.LR??'—')} / ${esc(e.batch??summary.batch??c.batch??'—')}</td><td>${num(e.epochs)}</td><td>${num(e.checkpoints_count)}</td><td>${stamp(e.modified||e.created_at)}</td><td>${button(translateStatic('결과 확인'),'experiment','subtle small','',`data-id="${esc(e.id)}"`)}</td></tr>`;}).join('')}</tbody></table></div>`;}
function simulation(){return ui`<div class="tab-row" role="tablist" aria-label="시뮬레이션 페이지">${[['collect',translateStatic('수집 설정 · 실행')],['sensors',translateStatic('센서 구성')],['datasets',say('시퀀스 분석 · 데이터셋','Sequences · datasets')],['recorded',say('저장 데이터 재생','Recorded playback')]].map(([key,label])=>`<button class="tab-button ${state.simTab===key?'active':''}" data-action="sim-tab" data-tab="${key}" role="tab" aria-selected="${state.simTab===key}">${label}</button>`).join('')}</div>${state.simTab==='sensors'?sensorPage():state.simTab==='datasets'?datasetPage():state.simTab==='recorded'?sequenceShell(state.datasets.filter(d=>d.kind==='collection'),state.previewId):collectionPage()}`;}
function collectionPage(){const s=state.settings,c=state.sensors;return ui`<div id="collection-progress">${collectionProgressHTML()}</div><div data-carla-local class="carla-local-mount">${localCarlaCard()}</div><div class="grid main-aside"><div class="stack"><details class="panel collapsible-panel" data-fold="collection-environment" ${panelIsOpen('collection-environment')?'open':''}>${foldSummary('collection-environment',translateStatic('시뮬레이션 환경'),translateStatic('선택한 타운마다 지정한 수의 주행 샘플을 수집합니다.'),'<span id="carla-badge"></span>')}<form id="collection-form"><div class="form-section"><div class="form-grid">${field('collection_name',translateStatic('수집 이름'),'',{hint:translateStatic('비워 두면 생성 시간을 기준으로 이름을 지정합니다.')})}${field('data_num',translateStatic('타운당 샘플 수'),c.data_num,{type:'number',min:1,max:1000,step:1,unit:'samples',required:true})}<div class="field span-all"><label>수집할 타운 <span class="unit">하나 이상 선택</span></label><div class="check-grid">${['Town01','Town02','Town03','Town04','Town05','Town06','Town07','Town10HD'].map(t=>check(`town_${t}`,t,c.towns?.includes(t))).join('')}</div></div></div></div><div class="form-section"><h3>차량 · 교통 · 환경</h3><div class="form-grid">${field('vehicle',translateStatic('Ego 차량'),s.vehicle,{hint:translateStatic('CARLA Blueprint ID · 기본 차량: Tesla Model 3')})}${field('weather',translateStatic('초기 날씨'),s.weather,{options:[['cycle',translateStatic('기존 날씨 순환')],['ClearNoon',translateStatic('맑음 · 정오')],'CloudyNoon','WetNoon','WetCloudyNoon','MidRainyNoon','HardRainNoon','SoftRainNoon','ClearSunset','CloudySunset'],hint:translateStatic('기존 날씨 순환 또는 지정 날씨를 선택합니다.')})}${field('npc_vehicles',translateStatic('NPC 차량'),s.npc_vehicles,{type:'number',min:0,max:200,step:1,unit:translateStatic('대')})}${field('npc_walkers',translateStatic('보행자'),s.npc_walkers,{type:'number',min:0,max:200,step:1,unit:translateStatic('명')})}${field('fps',translateStatic('시뮬레이션 주기'),s.fps,{type:'number',min:1,max:60,step:1,unit:'FPS'})}${field('preview_fps',translateStatic('미리보기 갱신'),s.preview_fps??24,{type:'number',min:1,max:60,step:1,unit:'FPS',hint:translateStatic('정수 1–60 FPS · 요청 빈도이며 실제 표시 속도는 수집·전송 성능에 따라 달라집니다.')})}</div></div>${drivingSettingsHTML(s,field,check)}${bevSettingsHTML(s,field,check)}<div class="form-section"><div class="keyvalue"><dt>활성 센서</dt><dd>${Object.keys(c.sensors||{}).map(k=>esc(sensorNames[k]||k)).join(', ')||translateStatic('없음')}</dd></div><div class="keyvalue"><dt>저장 경로</dt><dd class="mono">${esc(s.data_root)}</dd></div><div id="collection-feedback" class="inline-feedback"></div></div><div class="setting-actions"><button type="button" class="button subtle" data-action="sim-tab" data-tab="sensors">${icon('camera')}센서 설정</button><button type="submit" class="button">${icon('save')}수집 설정 저장</button></div></form></details>${manualControlHTML()}${panel(translateStatic('센서 미리보기'),ui`<div class="collection-live-scene"><div><div class="live-mode-label"><span class="dot cyan"></span> LIVE · ${say("최근 저장 센서 프레임","Latest saved sensor frame")}</div><div id="sensor-preview">${previewStage()}</div></div><aside class="scene-info"><section id="driving-runtime-info">${drivingTelemetryHTML(latest('collection'))}</section><section id="collection-scene-info">${sceneInformationHTML({},"live")}</section></aside></div><div id="collection-live-layers"></div><div id="collection-bev-legend" class="bev-legend"></div><div class="telemetry" id="collection-telemetry"></div><div class="panel-foot"><span id="preview-caption">수집 작업의 최신 저장 프레임을 표시합니다.</span></div>`,ui`<div class="preview-controls"><label class="check-inline"><input id="live-preview" type="checkbox" ${state.livePreview?'checked':''}>자동 갱신</label><select aria-label="미리보기 유형" id="preview-mode" class="select-control"><option value="camera">전방 카메라</option><option value="bev">BEV</option></select></div>`)}${logDetails('collection',ui`<pre class="log-panel" id="collection-log">수집 작업이 시작되면 실행 로그를 표시합니다.</pre>`)}</div><div class="stack"><details class="panel collapsible-panel" data-fold="carla-connection" ${panelIsOpen('carla-connection')?'open':''}>${foldSummary('carla-connection',translateStatic('CARLA 연결'),'',icon('server'))}<div class="panel-body"><dl><div class="keyvalue"><dt>서버 주소</dt><dd class="mono">${esc(s.carla_host)}:${esc(s.carla_port)}</dd></div><div class="keyvalue"><dt>현재 맵</dt><dd id="carla-map">${esc(state.carla.map||'—')}</dd></div><div class="keyvalue"><dt>상태</dt><dd id="carla-state">연결 확인 전</dd></div></dl><div class="inline-actions spaced" id="carla-actions"></div><div id="carla-message" class="inline-feedback"></div></div><div class="panel-foot"><a href="#settings" class="text-link">연결 주소 변경 ${icon('arrow')}</a></div></details><section class="panel sticky-aside"><div class="run-card"><h3>데이터 수집 실행</h3><p class="dependency-hint">설정을 저장하고 준비 검사를 통과하면 실제 CARLA 수집 작업을 시작합니다.</p><div id="collection-preflight"></div>${button(translateStatic('준비 상태 검사'),'check-collection','subtle','shield')}${button(translateStatic('데이터 수집 시작'),'start-collection','primary','play','id="start-collection" disabled')}</div></section></div></div>`;}
function previewStage(){return `<div class="preview-stage"><div class="preview-grid"></div><span class="preview-chip">Sensor preview</span>${empty('camera',translateStatic('미리보기 대기 중'),translateStatic('데이터 수집 중 자동 갱신을 켜면 카메라와 BEV를 확인할 수 있습니다.'))}</div>`;}
function sensorPage(){return ui`${window.SensorPreview?.html()||''}<form id="sensor-form"><div class="grid main-aside"><section class="panel"><div class="panel-head"><div><h2>수집 센서 구성</h2><p>센서를 활성화하고 해상도, 위치와 출력 채널을 설정합니다.</p></div>${icon('camera')}</div><div class="panel-body">${Object.keys(sensorNames).map(name=>{const enabled=Boolean(state.sensors.sensors?.[name]);const c=state.sensors.sensors?.[name]||sensorDefaults(name);const labels={width:[translateStatic('이미지 너비'),'px'],height:[translateStatic('이미지 높이'),'px'],fov:[translateStatic('시야각'),'°'],x:[translateStatic('X 위치'),'m'],y:[translateStatic('Y 위치'),'m'],z:[translateStatic('Z 높이'),'m'],yaw:['Yaw','°'],pitch:['Pitch','°'],roll:['Roll','°'],channels:[translateStatic('채널 수'),translateStatic('개')],range:[translateStatic('측정 거리'),'m'],points_per_second:[translateStatic('초당 포인트'),'points/s'],rotation_frequency:[translateStatic('회전 주파수'),'Hz'],upper_fov:[translateStatic('상단 시야각'),'°'],lower_fov:[translateStatic('하단 시야각'),'°']};return ui`<details class="sensor-card" ${enabled?'open':''}><summary>${icon(name==='lidar'?'layers':'camera')}<span>${sensorNames[name]}</span><span class="badge">${esc(name)}</span>${icon('chevron','chevron')}</summary><div class="sensor-fields"><label class="check-inline"><input name="enable_${name}" type="checkbox" ${enabled?'checked':''}>수집에 사용</label><div class="form-grid three spaced">${Object.entries(c).filter(([key])=>!['seg','depth','od'].includes(key)).map(([key,value])=>field(`${name}.${key}`,labels[key]?.[0]||key,value,{type:'number',step:['width','height','channels','points_per_second','rotation_frequency'].includes(key)?1:'any',unit:labels[key]?.[1]||''})).join('')}</div>${name!=='lidar'?`<div class="sensor-actions">${['seg','depth','od'].map(key=>`<label class="check-inline"><input name="${name}.${key}" type="checkbox" ${c[key]?'checked':''}>${{seg:'Segmentation',depth:'Depth',od:'Object detection'}[key]}</label>`).join('')}</div>`:''}</div></details>`;}).join('')}<div id="sensor-feedback" class="inline-feedback"></div></div></section><div class="stack"><section class="panel"><div class="run-card"><h3>센서 설정 저장</h3><p class="dependency-hint">RGB 카메라를 하나 이상 선택하세요. 위치는 Ego 차량 기준이며, 회전 각도는 도(°) 단위입니다.</p>${alertBox(translateStatic('센서 출력 채널은 학습 태스크와 일치해야 합니다. BEV 학습에는 선택한 카메라의 보정 정보가 필요합니다.'))}<button type="submit" class="button primary">${icon('save')}센서 설정 저장</button><button type="button" class="button subtle" data-action="sim-tab" data-tab="collect">수집 설정으로 돌아가기</button></div></section></div></div></form>`;}
function datasetPage(){const scenes=state.datasets.filter(d=>d.kind==='collection');return `${sequenceShell(scenes,state.previewId)}<div class="grid main-aside dataset-preparation"><details class="panel" open><summary class="panel-head"><h2>${translateStatic('수집된 Scene')}</h2><span class="faint">${say('학습·검증 분할','Train / validation split')}</span></summary>${scenes.length?`<div class="table-wrap"><table><thead><tr><th>Sequence / Scene</th><th>${translateStatic('샘플')}</th><th>${translateStatic('용도')}</th><th>${translateStatic('미리보기')}</th><th>${say('삭제','Delete')}</th></tr></thead><tbody>${scenes.map(d=>`<tr><td><strong>${esc(d.name)}</strong><small>${esc(d.town||d.path)}</small></td><td>${num(d.samples)}</td><td><select class="select-control" aria-label="${esc(d.name)} split" data-dataset-split="${esc(d.id)}"><option value="">${translateStatic('선택 안 함')}</option><option value="train">TRAIN</option><option value="val">VAL</option></select></td><td>${button(translateStatic('보기'),'dataset-preview','subtle small','camera',`data-id="${esc(d.id)}"`)}</td><td>${button(say('삭제','Delete'),'dataset-delete','danger small','',`data-id="${esc(d.id)}" aria-label="${esc(d.name)} ${say('삭제','delete')}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('database',translateStatic('수집된 Scene이 없습니다'),translateStatic('먼저 CARLA에서 데이터를 수집하거나 설정한 데이터 저장 경로에 기존 수집 데이터를 배치하세요.'))}</details><form id="dataset-form" class="panel"><div class="run-card"><h3>${translateStatic('학습 / 검증 데이터 준비')}</h3><p class="dependency-hint">${translateStatic('왼쪽에서 학습 Scene과 검증 Scene을 각각 선택하세요. 원본을 보존하고 선택한 분할을 별도 데이터셋으로 준비합니다.')}</p>${field('dataset_name',translateStatic('데이터셋 이름'),'',{required:true})}<p class="dependency-hint">${translateStatic('무작위 프레임 분할은 하지 않습니다. 같은 주행 장면이 양쪽에 포함되는 데이터 누수를 방지합니다.')}</p><div id="dataset-feedback" class="inline-feedback"></div><button class="button primary" type="submit" ${!scenes.length?'disabled':''}>${icon('database')}${translateStatic('선택한 Scene으로 준비')}</button></div></form></div>`;}
function training(){return ui`<div class="tab-row" role="tablist" aria-label="모델 학습 페이지">${[['setup',translateStatic('모델 · 학습 설정')],['monitor',translateStatic('학습 모니터링')],['queue',translateStatic('학습 대기열')]].map(([key,label])=>`<button class="tab-button ${state.trainTab===key?'active':''}" data-action="train-tab" data-tab="${key}" role="tab" aria-selected="${state.trainTab===key}">${label}${key==='queue'?` <span class="queue-count">${state.jobs.filter(j=>j.kind==='training'&&['Queued','Running','Pausing','Paused'].includes(j.status)).length}</span>`:''}</button>`).join('')}</div>${state.trainTab==='monitor'?trainingMonitor():state.trainTab==='queue'?trainingQueue():trainingSetup()}`;}
function modelCatalogEntries(name){const key={encoder:'encoders',decoder:'decoders',bev_decoder:'bev_decoders'}[name],rows=state.model_catalog?.[key];if(Array.isArray(rows)&&rows.length)return rows;return ({encoder:['ResNet','EfficientNet'],decoder:['FPN','Bi-FPN'],bev_decoder:[null,'ResNet','EfficientNet']}[name]||[]).map(id=>({id,label:id||translateStatic('None · 없음'),available:true}));}
const modelId=value=>value===null||value===undefined?'':String(value);
const modelCatalogLabel=row=>language==='en'?row.label_en||({ResNet:'ResNet-34 (legacy)',EfficientNet:'EfficientNet-B0 (legacy)'})[row.id]||row.label||row.id:row.label||row.id;
const modelReason=row=>{const reason=language==='en'?row?.reason_en||row?.reason:row?.reason;return language==='en'&&row?.reason_en?String(reason).replaceAll('ResNet-34 (기존)','ResNet-34 (legacy)').replaceAll('EfficientNet-B0 (기존)','EfficientNet-B0 (legacy)'):reason;};
function modelOptionMarkup(name,selected){return modelCatalogEntries(name).map(row=>{const value=modelId(row.id),label=row.id===null?translateStatic('None · 없음'):modelCatalogLabel(row),reason=row.available===false?modelReason(row)||translateStatic('현재 실행 환경에서 사용할 수 없습니다.'):'';return `<option value="${esc(value)}" ${value===modelId(selected)?'selected':''} ${row.available===false?'disabled':''} ${reason?`title="${esc(reason)}"`:''}>${esc(label)}${row.available===false?` · ${translateStatic('사용 불가')}`:''}</option>`;}).join('');}
function modelSelectField(name,label,value,hint){return `<div class="field"><label for="${name}">${label}</label><select id="${name}" name="${name}" aria-describedby="${name}-hint ${name}-availability">${modelOptionMarkup(name,value)}</select><small id="${name}-hint">${hint}</small><small id="${name}-availability" class="prerequisite-text"></small></div>`;}
function selectedModelValue(name){const input=document.querySelector(`#training-form [name="${name}"]`);return input?input.value:state.training.model?.[name];}
function modelSelectionBlocker(){for(const name of ['encoder','decoder','bev_decoder']){if(name==='bev_decoder'&&!(document.querySelector('[name="task_BEV"]')?.checked??state.training.model_conf?.BEV))continue;const row=modelCatalogEntries(name).find(item=>modelId(item.id)===modelId(selectedModelValue(name)));if(row?.available===false)return modelReason(row)||translateStatic('현재 실행 환경에서 사용할 수 없습니다.');}return '';}
function renderModelAvailability(){for(const name of ['encoder','decoder','bev_decoder']){const target=document.getElementById(`${name}-availability`);if(!target)continue;const row=modelCatalogEntries(name).find(item=>modelId(item.id)===modelId(selectedModelValue(name)));target.textContent=row?.available===false?modelReason(row)||translateStatic('현재 실행 환경에서 사용할 수 없습니다.'):'';}}
function applyEnvironment(data){if(data.capabilities)state.capabilities=data.capabilities;if(data.model_catalog){state.model_catalog=data.model_catalog;for(const name of ['encoder','decoder']){const select=document.querySelector(`#training-form [name="${name}"]`);if(select){const value=select.value;select.innerHTML=modelOptionMarkup(name,value);}}syncBEVDecoder();const catalog=document.querySelector('#model-catalog-notice');if(catalog)catalog.innerHTML=modelCatalogNotice();renderModelAvailability();}const environment=document.querySelector('#environment-info');if(environment)environment.innerHTML=dependenciesHTML();}
async function refreshModelEnvironment(){applyEnvironment(await api('/api/bootstrap'));}
function modelCatalogNotice(){const groups=[['encoder',translateStatic('이미지 인코더')],['decoder',translateStatic('이미지 디코더')],['bev_decoder',translateStatic('BEV 디코더')]];const unavailable=groups.flatMap(([name,label])=>modelCatalogEntries(name).filter(row=>row.available===false).map(row=>`<li><strong>${esc(label)} · ${esc(modelCatalogLabel(row))}</strong><span>${esc(modelReason(row)||translateStatic('현재 실행 환경에서 사용할 수 없습니다.'))}</span></li>`));return unavailable.length?`<details class="model-catalog-notice"><summary>${translateStatic('사용할 수 없는 모델과 이유')} (${unavailable.length})</summary><ul>${unavailable.join('')}</ul></details>`:'';}
const trainingSensorIds=Object.keys(sensorNames).filter(key=>key!=='front_cam_pv');
const trainingTaskIds=['BEV','Seg','Depth','od'];
let trainingOptionsRequest=0,trainingOptionsContext='';
function trainingOptionsDraft(){const form=document.querySelector('#training-form');return {sensor_use:Object.fromEntries(trainingSensorIds.map(key=>[key,form?Boolean(form.querySelector(`[name="sensor_${key}"]`)?.checked):Boolean(state.training.sensor_use?.[key])])),train_data:form?.querySelector('[name="train_data"]')?.value??state.settings.train_data,val_data:form?.querySelector('[name="val_data"]')?.value??state.settings.val_data,...((state.taskDraftSettings||state.training.task_settings)?{task_settings:state.taskDraftSettings||state.training.task_settings}:{})};}
const trainingOptionsKey=value=>JSON.stringify(value);
function trainingOptionCheck(group,key,label,checked){const name=`${group==='sensors'?'sensor':'task'}_${key}`;return `<div class="training-option" data-training-option="${group}:${key}"><label class="checkbox-tile"><input type="checkbox" name="${name}" ${checked?'checked':''} aria-describedby="option-reason-${name}"><span>${label}</span></label><small class="training-option-reason" id="option-reason-${name}"></small></div>`;}
function syncBEVDecoder(){const enabled=document.querySelector('[name="task_BEV"]')?.checked,select=document.querySelector('#bev_decoder');if(!select)return;const current=select.value;if(current)state.bevDecoderChoice=current;if(enabled){const options=modelCatalogEntries('bev_decoder').filter(row=>row.id!==null),preferred=state.bevDecoderChoice||state.training.model?.bev_decoder||'ResNet',choice=options.some(row=>row.id===preferred)?preferred:options.find(row=>row.available!==false)?.id||preferred;select.innerHTML=modelOptionMarkup('bev_decoder',choice);select.querySelector('option[value=""]')?.remove();select.value=choice;select.disabled=false;}else{select.innerHTML=`<option value="">${translateStatic('None · 없음')}</option>`;select.value='';select.disabled=true;}select.dataset.bevEnabled=String(Boolean(enabled));renderModelAvailability();}
function applyTrainingOptions(){const form=document.querySelector('#training-form');if(!form)return;const matching=trainingOptionsContext===trainingOptionsKey(trainingOptionsDraft());let changed=false;for(const group of ['sensors','tasks']){for(const key of group==='sensors'?trainingSensorIds:trainingTaskIds){const name=`${group==='sensors'?'sensor':'task'}_${key}`,input=form.querySelector(`[name="${name}"]`),wrap=input?.closest('.training-option');if(!input||!wrap)continue;const option=matching?state.training_options?.[group]?.[key]:null;const missingObjects=group==='tasks'&&key==='od'&&state.taskCatalog&&!state.taskCatalog.detection?.classes?.length;const unavailable=option?.available===false||missingObjects,pending=state.trainingOptionsPending||!matching||!option;input.disabled=unavailable||pending||Boolean(state.trainingOptionsError);wrap.classList.toggle('unavailable',unavailable);wrap.classList.toggle('pending',pending);if(unavailable&&input.checked){input.checked=false;changed=true;}const reason=missingObjects?say('양성 Bounding Box가 없는 데이터셋입니다.','The dataset contains no positive bounding boxes.'):unavailable?(language==='en'?option?.reason_en||option?.reason:option?.reason)||translateStatic('선택한 데이터셋에서 사용할 수 없습니다.'):'';wrap.querySelector('.training-option-reason').textContent=reason;input.title=reason;} }
if(changed){state.trainingDirty=true;captureDrafts();}syncBEVDecoder();const notice=document.querySelector('#training-options-feedback');if(notice){notice.className=`dependency-hint${state.trainingOptionsError?' prerequisite-text':''}`;notice.textContent=state.trainingOptionsError||((state.trainingOptionsPending||!matching)?translateStatic('학습·검증 파일과 센서별 라벨을 확인하고 있습니다.'):translateStatic('학습·검증 데이터가 모두 있는 입력과 출력만 선택할 수 있습니다.'));} }
async function refreshTrainingOptions(){const request=++trainingOptionsRequest,payload=trainingOptionsDraft(),key=trainingOptionsKey(payload);state.trainingOptionsPending=true;state.trainingOptionsError='';applyTrainingOptions();try{const options=await api('/api/training/options','POST',payload);if(request!==trainingOptionsRequest)return false;if(key!==trainingOptionsKey(trainingOptionsDraft()))return refreshTrainingOptions();state.training_options=options;trainingOptionsContext=key;state.trainingOptionsPending=false;applyTrainingOptions();if(key!==trainingOptionsKey(trainingOptionsDraft()))return refreshTrainingOptions();renderLive();return true;}catch(error){if(request!==trainingOptionsRequest)return false;state.trainingOptionsPending=false;state.trainingOptionsError=error.message;applyTrainingOptions();renderLive();return false;}}
const selectedEncoder=()=>document.querySelector('#training-form [name="encoder"]')?.value||state.training.model?.encoder||'ResNet';
function receivePretrained(value){if(!value)return;if(value.models){state.pretrained={...value,models:{...state.pretrained?.models,...value.models}};return;}const encoder=value.encoder||state.training.model?.encoder;if(!modelCatalogEntries('encoder').some(row=>row.id===encoder))return;const models={...state.pretrained?.models,[encoder]:value};state.pretrained={models,busy:Object.values(models).some(item=>item.status==='Running')};}
function pretrainedDescription(weights){if(weights.error||weights.status==='Failed')return weights.error||weights.message||translateStatic('사전학습 가중치 준비에 실패했습니다.');if(weights.ready)return translateStatic('검증된 가중치 파일을 학습에 사용합니다.');const descriptions={missing:translateStatic('사전학습 가중치가 없습니다. 학습 준비 확인에서 자동으로 준비합니다.'),checking:translateStatic('공식 사전학습 가중치를 준비하고 있습니다.'),downloading:translateStatic('공식 사전학습 가중치를 다운로드하고 있습니다.'),verifying:translateStatic('다운로드한 가중치 SHA256을 검증합니다.')};return descriptions[weights.phase]||weights.message||translateStatic('준비 상태 검사를 누르면 필요한 사전학습 가중치를 자동으로 내려받고 검증합니다.');}
function pretrainedHTML(){const encoder=selectedEncoder(),weights=state.pretrained?.models?.[encoder]||{},running=weights.status==='Running',ready=weights.ready===true,failed=weights.status==='Failed',progress=finite(weights.progress_pct)?Math.max(0,Math.min(100,weights.progress_pct)):null;return `<div class="pretrained-card"><div class="pretrained-heading"><strong>${translateStatic('사전학습 가중치')}</strong>${badge(ready?'Completed':weights.status||'Idle',ready?translateStatic('준비 완료'):undefined)}</div><div class="pretrained-model">${esc(encoder)}${weights.filename?` · <span class="mono">${esc(weights.filename)}</span>`:''}</div>${running?`<div class="progress-line"><span>${translateStatic('다운로드 · 파일 검증')}</span><span>${progress!==null?`${num(progress,1)}%`:translateStatic('진행률 확인 중')}</span></div><div class="track ${progress===null?'indeterminate':''}" ${progress!==null?`role="progressbar" aria-label="${translateStatic('사전학습 가중치 다운로드')}" aria-valuenow="${progress}" aria-valuemin="0" aria-valuemax="100"`:''}><span style="width:${progress??0}%"></span></div><p class="small faint">${installBytes(weights.downloaded_bytes)} / ${installBytes(weights.total_bytes)}</p>`:''}<p class="dependency-hint${failed?' prerequisite-text':''}">${esc(pretrainedDescription(weights))}</p>${running?`<p class="prerequisite-text small">${translateStatic('가중치 준비가 끝나면 실행 조건을 다시 확인합니다.')}</p>`:''}</div>`;}

function trainingSetup(){const t=state.training,s=state.settings;return ui`<form id="training-form"><div class="grid main-aside"><div class="stack"><section class="panel" data-training-stage="dataset"><div class="panel-head"><div><h2>학습 데이터</h2><p>준비한 데이터셋의 학습 / 검증 경로를 지정합니다.</p></div>${icon('database')}</div><div class="form-section"><div class="field"><label for="training-dataset-choice">학습 / 검증 데이터셋</label><select id="training-dataset-choice"><option value="">데이터셋 확인 중</option></select><p id="training-dataset-note" class="dependency-hint" role="status"></p></div><details class="task-advanced"><summary>고급 설정 · 데이터 경로 직접 지정</summary><div class="form-section form-grid">${field('train_data',translateStatic('학습 데이터 경로'),s.train_data,{required:true})}${field('val_data',translateStatic('검증 데이터 경로'),s.val_data,{required:true})}${field('dataset_sensor_config','수집 당시 센서 보정 파일',s.sensor_config,{required:true,cls:'span-all'})}</div></details><div class="inline-actions spaced"><button type="button" class="text-link" data-action="open-datasets">데이터셋 준비로 이동 ${icon('arrow')}</button></div></div></section><section class="panel" data-training-stage="inputs"><div class="panel-head"><h2>입력 센서</h2>${icon('camera')}</div><div class="form-section"><p id="training-options-feedback" class="dependency-hint" role="status"></p><div class="check-grid training-options-grid">${Object.entries(sensorNames).filter(([key])=>key!=='front_cam_pv').map(([key,label])=>trainingOptionCheck('sensors',key,label,t.sensor_use?.[key])).join('')}</div><p class="dependency-hint spaced" style="margin-bottom:0">전방 카메라는 필수입니다. BEV에는 선택한 카메라의 보정 정보가 필요합니다.</p></div></section><section class="panel" data-training-stage="outputs"><div class="panel-head"><h2>출력 태스크</h2>${icon('layers')}</div><div class="form-section"><div class="check-grid training-options-grid">${[['BEV','BEV'],['Seg','Segmentation'],['Depth','Depth'],['od','Object detection']].map(([key,label])=>trainingOptionCheck('tasks',key,label,t.model_conf?.[key])).join('')}</div><p class="dependency-hint spaced" style="margin-bottom:0">BEV: 위에서 본 도로 표현 · Segmentation: 픽셀별 영역 분류 · Depth: 거리 추정</p></div></section>${advancedSettingsShell()}${lossSettingsHTML(t,{field,esc})}<section class="panel" data-training-stage="model"><div class="panel-head"><div><h2>모델 구성</h2><p>기존 SDV에서 지원하는 인코더, 디코더와 출력 태스크를 사용합니다.</p></div>${icon('training')}</div><div class="form-section"><div class="form-grid">${modelSelectField('encoder',translateStatic('이미지 인코더'),t.model?.encoder,translateStatic('입력 영상에서 특징을 추출하는 네트워크'))}${modelSelectField('decoder',translateStatic('이미지 디코더'),t.model?.decoder,translateStatic('영상 특징을 Segmentation / Depth 출력으로 변환'))}${modelSelectField('bev_decoder',translateStatic('BEV 디코더'),t.model?.bev_decoder,translateStatic('BEV 태스크를 선택한 경우 사용'))}</div><div id="model-catalog-notice">${modelCatalogNotice()}</div></div></section><section class="panel" data-training-stage="parameters"><div class="panel-head"><h2>학습 파라미터</h2></div><div class="form-section"><div class="form-grid three">${field('Epochs',translateStatic('전체 Epoch'),t.Epochs,{type:'number',min:1,max:1000,step:1,unit:translateStatic('회'),required:true,hint:translateStatic('전체 학습 데이터를 반복하는 횟수')})}${field('batch','Batch size',t.batch,{type:'number',min:1,max:64,step:1,unit:'samples',required:true})}${field('LR','Learning rate',t.LR,{type:'number',min:.000001,max:1,step:'any',required:true})}${field('optimizer','Optimizer',Object.keys(t.opt_checkboxes||{}).find(k=>t.opt_checkboxes[k]),{options:['Adam','AdamW','SGD']})}${field('width',translateStatic('입력 너비'),t.width,{type:'number',min:64,max:1920,step:32,unit:'px',hint:translateStatic('32의 배수 · 객체 탐지 선택 시 128의 배수')})}${field('height',translateStatic('입력 높이'),t.height,{type:'number',min:64,max:1080,step:32,unit:'px',hint:translateStatic('32의 배수 · 객체 탐지 선택 시 128의 배수')})}</div></div><div class="form-section"><h3>Prediction 기록</h3><div class="form-grid three">${field('train_preview_every',translateStatic('TRAIN 기록 간격'),t.monitor?.train_preview_every??100,{type:'number',min:0,max:1000000,step:1,unit:'steps',hint:translateStatic('0은 끄기 · 고정 TRAIN 샘플의 Prediction을 저장합니다.')})}${field('val_preview_every',translateStatic('VAL 기록 간격'),t.monitor?.val_preview_every??1,{type:'number',min:1,max:1000,step:1,unit:'epochs',hint:translateStatic('같은 데이터셋의 고정 샘플 4개를 기록합니다.')})}${field('train_preview_basis','TRAIN 기록 기준',t.monitor?.train_preview_basis||'epoch',{options:[['epoch','매 Epoch 내부 Step'],['global','전체 누적 Step (기존 방식)']]})}${field('preview_max_mib','Prediction PNG 용량 한도',t.monitor?.preview_max_mib??1024,{type:'number',min:1,max:102400,step:1,unit:'MiB',hint:'한도에 도달하면 새 이미지 기록만 멈춥니다. 기존 이미지는 보존합니다.'})}${field('preview_samples',translateStatic('고정 VAL 샘플'),4,{type:'number',readonly:true,unit:translateStatic('개')})}</div><h3 class="spaced">Checkpoint 저장</h3><div class="check-grid">${check('save_Last_Epoch',translateStatic('마지막 Epoch'),t.save_checkboxes?.Last_Epoch!==false)}${check('save_Best_Loss',translateStatic('최저 검증 Loss'),t.save_checkboxes?.Best_Loss!==false)}</div><p class="dependency-hint spaced" style="margin-bottom:0">마지막 Epoch는 매 Epoch 완료 시, 최저 검증 Loss는 지표가 개선될 때 Checkpoint를 갱신합니다.</p><div id="training-feedback" class="inline-feedback"></div></div><div class="setting-actions"><button type="submit" class="button">${icon('save')}학습 설정 저장</button></div></section></div><aside class="stack"><section class="panel sticky-aside"><div class="run-card"><h3>새 학습 실험</h3>${field('training_name',translateStatic('실험 이름'),'',{hint:translateStatic('비워 두면 생성 시간으로 구분합니다.')})}<div class="spaced" id="training-pretrained">${pretrainedHTML()}</div><div class="spaced" id="training-preflight"></div><button class="button subtle" type="button" data-action="check-training">${icon('shield')}준비 상태 검사</button><button class="button primary" type="button" data-action="start-training" id="start-training" disabled>${icon('play')}학습 대기열에 추가</button><p class="dependency-hint spaced">실행 중에도 새 모델을 추가할 수 있습니다. 각 작업의 설정과 데이터 경로는 추가 시점에 고정됩니다.</p><div id="training-current"></div></div></section></aside></div></form>`;}
function trainingMonitor(){const job=latest('training');return `<div class="grid main-aside training-monitor-layout"><div class="stack">${panel(translateStatic('학습 진행 상태'),`<div id="training-job">${job?jobCard(job):empty('training',translateStatic('아직 시작한 학습이 없습니다'),translateStatic('모델과 데이터를 설정한 후 학습을 시작하세요.'),button(translateStatic('학습 설정 열기'),'train-tab','subtle small','settings','data-tab="setup"'))}</div>`,button(translateStatic('학습 대기열'),'train-tab','subtle small','layers','data-tab="queue"'))}${predictionGalleryShell('training',job?.id||'')}${panel(translateStatic('학습 지표'),`<div id="training-chart" class="training-chart-large"></div>`,ui`<div class="chart-toolbar"><select id="train-metric" class="select-control" aria-label="학습 지표 선택"><option>지표 대기 중</option></select></div>`)}${panel(translateStatic('태스크별 Best 지표'),`<div id="training-best-metrics"></div>`,`<select id="best-metric-split" class="select-control compact-select" aria-label="${translateStatic('지표 데이터 분할')}"><option value="val">VAL</option><option value="train">TRAIN</option></select>`)}${logDetails('training',ui`<pre class="log-panel" id="training-log">학습 작업을 시작하면 실제 프로세스 출력이 표시됩니다.</pre>`)} </div><aside class="stack">${panel(translateStatic('현재 실험'),`<div class="panel-body" id="training-summary">${trainingSummary(job)}</div>`)}${panel('Checkpoint',`<div id="training-checkpoints">${empty('save',translateStatic('저장 기록 대기 중'),translateStatic('학습 결과 파일이 생성되면 실험 결과에서 Checkpoint를 확인할 수 있습니다.'))}</div>`,ui`<a href="#results" class="text-link">결과 확인 ${icon('arrow')}</a>`)}${panel(translateStatic('학습 작업 기록'),`<div id="training-history"></div>`)}</aside></div>`;}

function checkpointHTML(job){const events=job?.metrics||[];const latestEpoch=[...events].reverse().find(e=>(e.event||e.type)==='training_epoch');if(!latestEpoch)return empty('save',translateStatic('저장 기록 대기 중'),translateStatic('Epoch 완료 후 Checkpoint 기록이 표시됩니다.'));const files=[[translateStatic('최저 검증 Loss'),latestEpoch.checkpoint],[translateStatic('마지막 Epoch'),latestEpoch.last_checkpoint]];return ui`<ul class="file-list">${files.map(([label,path])=>`<li>${icon('save')}<div class="file-main">${label}<small title="${esc(path||'')}">${path?esc(String(path).split('/').at(-1)):translateStatic('저장 비활성화')}</small></div>${path?badge('Completed',translateStatic('경로 기록')):badge('Idle',translateStatic('꺼짐'))}</li>`).join('')}</ul><div class="panel-foot">Epoch ${num(latestEpoch.epoch)} 완료 이벤트 기준 · 다운로드는 실험 결과에서 확인</div>`;}
function trainingSummary(job){const t=job?.config||state.training;return `<dl>${[[translateStatic('실험'),job?.name||'—'],[translateStatic('인코더'),t.model?.encoder||'—'],[translateStatic('이미지 디코더'),t.model?.decoder||'—'],[translateStatic('BEV 디코더'),t.model?.bev_decoder||translateStatic('None · 없음')],['Optimizer',optimizerName(t)],['Batch size',t.batch],['Learning rate',t.LR],[translateStatic('입력 센서'),Object.keys(t.sensor_use||{}).filter(k=>t.sensor_use[k]).join(', ')||'—'],[translateStatic('태스크'),Object.keys(t.model_conf||{}).filter(k=>t.model_conf[k]).join(', ')||'—'],['태스크 Loss',Object.entries(t.losses||{}).filter(([key])=>t.model_conf?.[key]).map(([key,value])=>`${key}: ${value.name} × ${value.weight}`).join(' · ')||'기존 기본 Loss'],[translateStatic('시작 시간'),stamp(job?.started_at)]].map(([k,v])=>`<div class="keyvalue"><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>`;}
function metricsFromJob(job){const groups=new Map();for(const e of job?.metrics||[]){if(e.points&&e.name){groups.set(`${e.name}-${e.split}`,e);continue;}const data=e.metrics||{};const isStep=(e.event||e.type)==='training_step';const x=isStep?(e.global_step??e.step):(e.epoch??e.global_step??e.step);if(!finite(x))continue;for(const [key,y] of Object.entries(data)){if(!finite(y))continue;const m=/^(train|val|test)_(.*)$/.exec(key);const split=m?.[1]||e.split||'observed',name=m?.[2]||key;const x_label=isStep?'step':e.epoch!==undefined?'epoch':'step';const id=`${name}-${split}-${x_label}`;if(!groups.has(id))groups.set(id,{name,split,x_label,points:[]});groups.get(id).points.push({x,y});}}return [...groups.values()];}
const chartColors=['#42c8ea','#9c99fc','#53c99d','#edbb66','#f08091','#83aaff'];
function chartHTML(series,description=''){const axes=[...new Set(series.map(s=>s.x_label||'epoch'))];if(axes.length>1)return axes.map(axis=>ui`<div class="panel-head"><h2>${esc(axis)} 기준 기록</h2></div>${chartHTML(series.filter(s=>(s.x_label||'epoch')===axis),description)}`).join('');const valid=series.map(s=>({...s,points:s.points.filter(p=>finite(p.x)&&finite(p.y))})).filter(s=>s.points.length);if(!valid.length)return empty('activity',translateStatic('아직 기록된 지표가 없습니다'),translateStatic('학습이 진행되어 실제 지표가 기록되면 그래프가 표시됩니다.'));const points=valid.flatMap(s=>s.points),xs=points.map(p=>p.x),ys=points.map(p=>p.y);let xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys),ymax=Math.max(...ys);if(xmin===xmax){xmin-=.5;xmax+=.5;}if(ymin===ymax){ymin-=Math.abs(ymin)*.1||.5;ymax+=Math.abs(ymax)*.1||.5;}const pad=(ymax-ymin)*.08;ymin-=pad;ymax+=pad;const left=65,right=625,top=18,bottom=204;const xp=x=>left+(x-xmin)/(xmax-xmin)*(right-left),yp=y=>bottom-(y-ymin)/(ymax-ymin)*(bottom-top);const format=v=>finite(v)?v.toFixed(3):'—';return ui`<div class="chart"><svg viewBox="0 0 645 245" role="img" aria-label="${esc(description||valid.map(s=>`${s.name} ${s.split}`).join(', '))} 실제 학습 지표 그래프"><title>${esc(description||translateStatic('저장된 실험 지표'))}</title>${[0,.25,.5,.75,1].map(v=>{const y=top+v*(bottom-top);return `<path d="M${left} ${y}H${right}" stroke="#29384b" stroke-dasharray="3 5"/><text x="${left-12}" y="${y+3}" text-anchor="end">${format(ymax-v*(ymax-ymin))}</text>`;}).join('')}${[0,.25,.5,.75,1].map(v=>`<text x="${left+v*(right-left)}" y="${bottom+19}" text-anchor="middle">${format(xmin+v*(xmax-xmin))}</text>`).join('')}<text class="axis-title" x="${right}" y="241" text-anchor="end">${esc(valid[0].x_label||'epoch')}</text>${valid.map((s,i)=>`<polyline points="${s.points.map(p=>`${xp(p.x)},${yp(p.y)}`).join(' ')}" fill="none" stroke="${chartColors[i%chartColors.length]}" stroke-width="2" stroke-linejoin="round"/>${s.points.length<70?s.points.map(p=>`<circle cx="${xp(p.x)}" cy="${yp(p.y)}" r="2.5" fill="${chartColors[i%chartColors.length]}"><title>${esc(`${s.label||s.name} / ${s.split}: ${p.x} → ${p.y}`)}</title></circle>`).join(''):''}`).join('')}</svg></div><div class="chart-legend">${valid.map((s,i)=>`<span><i style="background:${chartColors[i%chartColors.length]}"></i>${esc(`${s.label||metricLabel(s.name)} · ${String(s.split||'source unknown').toUpperCase()} · ${s.x_label||'epoch'}`)}</span>`).join('')}</div>`;}
function renderTrainingChart(){const target=document.querySelector('#training-chart');if(!target)return;const series=metricsFromJob(latest('training'));const names=[...new Set(series.map(s=>s.name))];if(!names.includes(state.trainMetric))state.trainMetric=names[0]||'';document.querySelector('#train-metric').innerHTML=names.length?names.map(name=>`<option value="${esc(name)}" ${state.trainMetric===name?'selected':''}>${esc(metricLabel(name))}</option>`).join(''):translateStatic('<option>지표 대기 중</option>');target.innerHTML=chartHTML(series.filter(s=>s.name===state.trainMetric));}
function results(){return ui`<div class="experiment-toolbar"><label><span class="hide">실험 이름 검색</span><input id="experiment-search" placeholder="실험 이름 검색" aria-label="실험 이름 검색"></label><div class="inline-actions"><span class="small muted" id="compare-count">${state.selected.size}개 선택</span>${button(translateStatic('선택한 실험 비교'),'compare','subtle','compare','id="compare-button" disabled')}</div></div><section class="panel"><div class="panel-head"><h2>실험 기록 <span class="faint small">${state.experiments.length}개</span></h2><span class="small faint">실제 결과 폴더 기준</span></div><div id="experiment-list">${experimentTable(state.experiments,true)}</div></section><div id="result-detail" class="spaced"></div>`;}
function artifactList(detail){const files=detail.artifacts||[];return files.length?`<ul class="file-list">${files.map(f=>ui`<li>${icon(f.kind==='checkpoint'?'save':f.kind==='image'?'camera':'file')}<div class="file-main">${esc(f.name)}<small>${bytes(f.size)} · ${stamp(f.modified)}</small></div><a class="icon-button" aria-label="${esc(f.name)} 다운로드" href="/api/experiments/${encodeURIComponent(detail.id)}/artifact?path=${encodeURIComponent(f.path)}" download>${icon('download')}</a></li>`).join('')}</ul>`:empty('folder',translateStatic('저장된 파일이 없습니다'),translateStatic('학습 중 생성된 파일이 여기에 표시됩니다.'));}
function renderDetail(){const target=document.querySelector('#result-detail');if(!target||!state.detail)return;const d=state.detail,metrics=d.metrics||[],names=[...new Set(metrics.map(m=>m.name))];if(!names.includes(state.metric))state.metric=names[0]||'';target.innerHTML=ui`<div class="page-heading"><div><h1 style="font-size:20px">${esc(d.name)}</h1><p>${esc(d.path||'')}</p></div><div class="heading-actions"><a class="button subtle" href="/api/experiments/${encodeURIComponent(d.id)}/export">${icon('download')}실험 내보내기</a>${button(translateStatic('상세 닫기'),'close-detail','subtle','close')}</div></div>${d.warnings?.length?`<div class="system-warning">${alertBox(d.warnings.map(esc).join('<br>'),'info')}</div>`:''}<div class="grid main-aside"><div class="stack">${panel(translateStatic('성능 지표'),`<div id="result-chart">${chartHTML(metrics.filter(m=>m.name===state.metric))}</div>`,ui`<div class="chart-toolbar"><select id="result-metric" aria-label="실험 지표 선택" class="select-control">${names.length?names.map(name=>`<option value="${esc(name)}" ${state.metric===name?'selected':''}>${esc(metricLabel(name))}</option>`).join(''):translateStatic('<option>지표 없음</option>')}</select></div>`)}${panel(translateStatic('태스크별 Best 지표'),bestMetricTable(metrics,'val',d.best_metrics||{}))}${predictionGalleryShell('result',d.id)}${panel(translateStatic('기록된 최종 지표'),metricTable(metrics))}${panel(translateStatic('상세 설정'),`<pre class="config-display">${esc(JSON.stringify(d.config||{},null,2))}</pre>`)}</div><div class="stack">${panel(translateStatic('Checkpoint · 결과 파일'),artifactList(d))}</div></div>`;refreshPredictionGallery('result',true);}
function metricTable(metrics){const rows=metrics.filter(m=>m.points?.length).map(m=>({...m,last:m.points.at(-1)}));return rows.length?ui`<div class="table-wrap"><table><thead><tr><th scope="col">Metric</th><th scope="col">분할</th><th scope="col">마지막 값</th><th scope="col">기록 기준</th></tr></thead><tbody>${rows.map(m=>`<tr><td>${esc(metricLabel(m.name))}</td><td>${esc(m.split)}</td><td>${metricValue(m.last.y)}</td><td>${esc(m.x_label)} ${num(m.last.x)}</td></tr>`).join('')}</tbody></table></div>`:empty('results',translateStatic('기록된 성능 지표가 없습니다'),translateStatic('학습 지표 파일이 생성되어야 비교할 수 있습니다.'));}
async function comparison(){const ids=[...state.selected];if(ids.length<2)return toast(translateStatic('비교할 실험을 2개 이상 선택하세요.'),true);const target=document.querySelector('#result-detail');target.innerHTML=translateStatic('<div class="loading-line"><span class="spinner"></span>실험 지표를 불러오는 중입니다.</div>');const all=await Promise.all(ids.map(id=>api(`/api/experiments/${encodeURIComponent(id)}`)));const keys=[...new Set(all.flatMap(d=>(d.metrics||[]).filter(m=>!(d.metric_registry?.[`${m.split}_${m.name}`]?.detail||/_class_\d+/.test(m.name))).map(m=>`${m.name} (${m.split})`)))];target.innerHTML=ui`<section class="panel"><div class="panel-head"><h2>선택한 실험 비교</h2>${button(translateStatic('비교 닫기'),'close-detail','subtle small','close')}</div><div class="comparison-note">동일한 지표와 데이터 분할만 비교하세요. 실험별 입력·데이터·Epoch가 다르면 직접 비교에 주의가 필요합니다.</div><div class="table-wrap"><table><thead><tr><th scope="col">Metric / 설정</th>${all.map(d=>`<th scope="col">${esc(d.name)}</th>`).join('')}</tr></thead><tbody>${[[translateStatic('인코더'),d=>experimentConfig(d).model?.encoder],[translateStatic('태스크'),d=>Object.keys(experimentConfig(d).model_conf||{}).filter(k=>experimentConfig(d).model_conf[k]).join(', ')],['Epoch',d=>experimentConfig(d).Epochs],['Optimizer',d=>optimizerName(experimentConfig(d))],['Batch size',d=>experimentConfig(d).batch],[translateStatic('학습률'),d=>experimentConfig(d).LR]].map(([label,fn])=>`<tr><td>${label}</td>${all.map(d=>`<td>${esc(fn(d)??'—')}</td>`).join('')}</tr>`).join('')}${keys.map(key=>`<tr><td>${esc(key)}</td>${all.map(d=>{const m=(d.metrics||[]).find(m=>`${m.name} (${m.split})`===key);return `<td>${metricValue(m?.points?.at(-1)?.y)}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div>${keys.length?ui`<div class="panel-head"><h2>지표 추이</h2><select id="compare-metric" class="select-control" style="max-width:220px" aria-label="비교 지표">${keys.map(k=>`<option>${esc(k)}</option>`).join('')}</select></div><div id="compare-chart"></div>`:empty('activity',translateStatic('비교할 지표가 없습니다'),translateStatic('선택한 실험에 실제 학습 기록이 필요합니다.'))}</section><div id="prediction-comparison" class="spaced"></div>`;state.compareDetails=all;loadPredictionComparison(all);if(keys.length)renderCompareChart(keys[0]);target.scrollIntoView({block:'start',behavior:'smooth'});}
function renderCompareChart(key){const series=(state.compareDetails||[]).flatMap(d=>(d.metrics||[]).filter(m=>`${m.name} (${m.split})`===key).map(m=>({...m,label:d.name})));const axes=[...new Set(series.map(s=>s.x_label))];document.querySelector('#compare-chart').innerHTML=axes.length>1?`<div class="panel-body">${alertBox(translateStatic('기록의 X축 기준이 서로 달라 그래프를 겹쳐 표시하지 않습니다. 상세 결과에서 각 기록을 확인하세요.'))}</div>`:chartHTML(series,key);}
const localConnectionLocked=()=>previewBusy()||state.carla_local?.task?.status==='Running'||state.carla_local?.engine?.running===true;
const installBytes=value=>finite(value)&&value>=0?value>=1073741824?`${num(value/1073741824,1)} GiB`:value>=1048576?`${num(value/1048576,1)} MiB`:`${num(value/1024,1)} KiB`:translateStatic('확인 중');
function settingsLockNotice(){if(active())return `<div class="system-warning">${alertBox(translateStatic('연구 작업 실행 중에는 시스템 설정을 변경할 수 없습니다. 현재 작업을 완료하거나 중지한 후 저장하세요.'))}</div>`;if(previewBusy())return `<div class="system-warning">${alertBox(translateStatic('센서 프리뷰 실행 중에는 CARLA 호스트·포트와 Python 경로를 변경할 수 없습니다. 프리뷰를 중지한 뒤 변경하세요. 다른 설정은 편집할 수 있습니다.'))}</div>`;if(localConnectionLocked())return `<div class="system-warning">${alertBox(translateStatic('로컬 CARLA가 설치·실행 중입니다. CARLA 호스트·포트와 Python 경로는 종료 후 변경할 수 있습니다. 수집 환경과 저장 경로는 편집할 수 있습니다.'))}</div>`;return '';}
function localCarlaCard(){const l=state.carla_local,t=l?.task||{},e=l?.engine||{},taskRunning=t.status==='Running',engineRunning=e.running===true,collecting=active()?.kind==='collection',isKnown=l!==null;const ready=engineRunning&&e.ready;const startDisabled=!state.online||!isKnown||l.local_allowed!==true||taskRunning||engineRunning||Boolean(active())||previewBusy();const stoppable=taskRunning||(engineRunning&&e.owned===true);const stopDisabled=!state.online||!stoppable||collecting||previewBusy()||t.stop_requested===true;const label=ready?translateStatic('CARLA 실행 중'):taskRunning?translateStatic('CARLA 준비 중'):engineRunning?translateStatic('CARLA 실행 중'):l?.installed?translateStatic('CARLA 실행'):translateStatic('CARLA 설치 후 실행');const reason=previewBusy()?previewBlockReason():collecting?translateStatic('데이터 수집 중에는 CARLA를 종료할 수 없습니다. 수집 작업을 먼저 중지하세요.'):active()?translateStatic('연구 작업이 실행 중입니다. 작업을 완료하거나 중지한 후 CARLA를 준비하세요.'):l?.local_allowed===false?l.local_reason||translateStatic('현재 서버 주소에서는 로컬 CARLA를 실행할 수 없습니다. 로컬 호스트로 변경하거나 외부 서버에 연결하세요.'):engineRunning&&!e.owned?translateStatic('외부에서 실행한 CARLA입니다. 이 화면에서는 해당 프로세스를 종료하지 않습니다.'):'';const phase=({queued:translateStatic('시작 준비'),checking:translateStatic('Python 클라이언트 확인'),client_check:translateStatic('Python 클라이언트 확인'),client_installing:translateStatic('Python 클라이언트 설치'),download:translateStatic('다운로드'),downloading:translateStatic('다운로드'),extract:translateStatic('압축 해제'),extracting:translateStatic('압축 해제'),install:translateStatic('설치'),installing:translateStatic('설치'),starting:translateStatic('엔진 실행'),launching:translateStatic('엔진 실행'),waiting:translateStatic('서버 준비 대기'),waiting_rpc:translateStatic('CARLA 연결 대기'),ready:translateStatic('실행 준비 완료'),installed:translateStatic('설치 완료'),completed:translateStatic('완료'),stopping:translateStatic('정상 종료 중'),stopped:translateStatic('중지'),failed:translateStatic('실패')})[t.phase]||t.phase||translateStatic('작업 대기');const progress=finite(t.progress_pct)?Math.min(100,Math.max(0,t.progress_pct)):null;const taskBadge=taskRunning?badge('Running',t.stop_requested?translateStatic('중지 처리 중'):phase):ready?badge('Completed',translateStatic('실행 준비 완료')):t.status==='Failed'?badge('Failed',translateStatic('실패')):engineRunning?badge('Running',translateStatic('엔진 실행 중')):l?.installed?badge('Completed',translateStatic('설치됨')):isKnown?badge('Idle',translateStatic('미설치')):badge('Idle',translateStatic('확인 중'));return ui`<details class="panel carla-local-panel collapsible-panel" data-fold="local-carla" ${panelIsOpen('local-carla')?'open':''}>${foldSummary('local-carla',`${icon('server')} ${translateStatic('로컬 CARLA 설치 · 실행')}`,translateStatic('설치·실행 시 엔진과 필요한 Python 클라이언트를 준비합니다.'),taskBadge)}<div class="local-carla-layout"><div class="local-carla-overview"><dl><div class="keyvalue"><dt>CARLA 버전</dt><dd>${esc(l?.version||l?.required_version||translateStatic('확인 중'))}</dd></div><div class="keyvalue"><dt>설치 경로</dt><dd class="mono">${esc(l?.install_path||translateStatic('확인 중'))}</dd></div><div class="keyvalue"><dt>다운로드 용량</dt><dd>${installBytes(l?.total_bytes)}</dd></div><div class="keyvalue"><dt>설치에 필요한 여유 공간</dt><dd>${installBytes(l?.required_free_bytes)}<small class="local-disk-note">현재 여유 ${installBytes(l?.free_bytes)}</small></dd></div>${engineRunning?ui`<div class="keyvalue"><dt>실행 서버</dt><dd>${esc(e.host||state.settings.carla_host)}:${esc(e.port||state.settings.carla_port)}${e.pid?` · PID ${esc(e.pid)}`:''}</dd></div>`:''}</dl><details class="local-source"><summary>다운로드 출처 확인</summary><div class="path-text">${esc(l?.source_url||translateStatic('상태 확인 후 다운로드 출처를 표시합니다.'))}</div>${l?.fallback_url?ui`<div class="path-text">대체 다운로드 출처<br>${esc(l.fallback_url)}</div>`:''}</details></div><div class="local-carla-control">${(taskRunning||t.status==='Failed'||t.status==='Stopped'||t.status==='Completed')?`<div class="local-task"><div class="local-task-title"><strong>${ready?translateStatic('실행 준비 완료'):esc(phase)}</strong><span>${progress!==null?`${num(progress,1)}%`:taskRunning?translateStatic('진행률 확인 중'):''}</span></div>${taskRunning||progress!==null?`<div class="track ${progress===null?'indeterminate':''}" ${progress!==null?ui`role="progressbar" aria-label="CARLA ${esc(phase)} 진행률" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${progress}"`:''}><span style="width:${progress??0}%"></span></div>`:''}${finite(l?.download_bytes)&&l.download_bytes>0?ui`<div class="local-download-count">다운로드 ${installBytes(l.download_bytes)} / ${installBytes(l.total_bytes)}</div>`:''}<p class="local-task-message ${t.status==='Failed'?'error-text':''}" role="status">${esc(t.message||translateStatic('작업 상태를 확인하고 있습니다.'))}</p>${t.started_at?ui`<div class="small faint">시작 ${stamp(t.started_at)} · 경과 ${elapsed({...t,finished_at:taskRunning?null:t.updated_at})}</div>`:''}</div>`:ui`<p class="dependency-hint">${l?.installed?translateStatic('설치된 CARLA 엔진을 실행합니다.'):translateStatic('CARLA 엔진을 내려받아 설치하고 실행합니다.')} 연구 Python에 carla==0.9.15가 없으면 해당 클라이언트만 자동 설치합니다. 다른 연구 패키지는 변경하지 않습니다. 버전이 다르거나 손상된 기존 클라이언트는 자동 덮어쓰지 않습니다.</p>`}${reason?`<div class="local-disabled-reason">${icon('info')}<span>${esc(reason)}</span></div>`:''}${l?.error?`<div class="local-disabled-reason error-text">${icon('alert')}<span>${esc(l.error)}</span></div>`:''}${state.localError?`<div class="local-disabled-reason error-text">${icon('alert')}<span>${esc(state.localError)}</span></div>`:''}<div class="local-main-actions">${button(label,'carla-local-prepare','primary',l?.installed?'play':'download',`${startDisabled?'disabled':''} title="${esc(reason||(taskRunning?translateStatic('CARLA 준비 작업이 진행 중입니다.'):engineRunning?translateStatic('CARLA 엔진이 이미 실행 중입니다.'):translateStatic('CARLA를 설치하고 실행합니다.')))}"`)}${button(translateStatic('설치만'),'carla-local-install','subtle','download',`${startDisabled||l?.installed?'disabled':''} title="${previewBusy()?previewBlockReason():l?.installed?translateStatic('CARLA가 이미 설치되어 있습니다.'):translateStatic('Python 클라이언트 없이 엔진 다운로드·압축 해제만 진행합니다.')}"`)}${button(taskRunning&&!engineRunning?translateStatic('준비 중지'):translateStatic('CARLA 종료'),'carla-local-stop','danger','stop',`${stopDisabled?'disabled':''} title="${esc(previewBusy()?previewBlockReason():collecting?translateStatic('수집 작업을 먼저 중지하세요.'):!stoppable?translateStatic('이 화면에서 관리 중인 작업이나 엔진이 없습니다.'):translateStatic('설치 준비 또는 관리 중인 CARLA 엔진을 중지합니다.'))}"`)}</div><div class="local-sub-actions">${button(translateStatic('상태 새로고침'),'carla-local-refresh','subtle small','refresh')}${button(translateStatic('설치 · 엔진 로그'),'carla-local-logs','subtle small','terminal')}</div></div></div></details>`;}
async function refreshLocalCarla(quiet=false){try{adopt({carla_local:await api('/api/carla/local')});state.localError='';renderLive();if(!quiet)toast(translateStatic('로컬 CARLA 상태를 확인했습니다.'));return state.carla_local;}catch(error){state.localError=error.message;renderLive();if(!quiet)throw error;}}
async function startLocalCarla(operation){if(previewBusy())throw new Error(previewBlockReason());const l=await refreshLocalCarla(true);if(!l)throw new Error(translateStatic('로컬 CARLA 설치 상태를 먼저 확인하세요.'));if(l.local_allowed!==true)throw new Error(l.local_reason||translateStatic('현재 서버 주소에서는 로컬 CARLA를 실행할 수 없습니다.'));if(l.task?.status==='Running'||l.engine?.running)throw new Error(translateStatic('CARLA 준비 작업이나 엔진이 이미 실행 중입니다.'));if(active())throw new Error(translateStatic('연구 작업을 완료하거나 중지한 뒤 CARLA를 준비하세요.'));const installOnly=operation==='install';const title=installOnly?translateStatic('CARLA를 설치할까요?'):l.installed?translateStatic('CARLA 엔진을 실행할까요?'):translateStatic('CARLA를 설치하고 실행할까요?');const message=installOnly?translateStatic('CARLA 엔진 패키지를 다운로드하고 설치 경로에 압축을 풉니다. Python 클라이언트 없이 진행하며 엔진은 실행하지 않습니다.'):ui`${l.installed?translateStatic('설치된 CARLA 엔진을 실행합니다.'):translateStatic('CARLA 엔진을 내려받아 설치하고 실행합니다.')} 선택한 연구 Python에 carla==0.9.15가 없으면 해당 클라이언트만 자동 설치한 후 엔진을 준비합니다. 다른 연구 패키지는 변경하지 않으며 기존 클라이언트의 버전 불일치·손상은 자동 덮어쓰지 않습니다. RPC 연결 준비가 끝나면 자동으로 연결됩니다.`;const detail=ui`<div class="keyvalue"><dt>설치 대상</dt><dd class="mono">${esc(l.install_path)}</dd></div><div class="keyvalue"><dt>버전</dt><dd>${esc(l.version||l.required_version||translateStatic('확인 중'))}</dd></div>${!l.installed?ui`<div class="keyvalue"><dt>다운로드 / 필요 여유 공간</dt><dd>${installBytes(l.total_bytes)} / ${installBytes(l.required_free_bytes)}</dd></div><div class="keyvalue"><dt>현재 여유 공간</dt><dd>${installBytes(l.free_bytes)}</dd></div>`:''}${!installOnly?ui`<div class="keyvalue"><dt>연구 Python</dt><dd class="mono">${esc(state.settings.python_executable)}</dd></div><div class="keyvalue"><dt>엔진 연결 주소</dt><dd>${esc(state.settings.carla_host)}:${esc(state.settings.carla_port)}</dd></div>`:''}`;if(!await confirmAction(title,message,installOnly?translateStatic('설치 시작'):l.installed?translateStatic('엔진 실행'):translateStatic('설치 후 실행'),detail))return;const result=await api('/api/carla/local/start','POST',{operation});adopt({carla_local:result.carla_local||result});state.localError='';renderLive();toast(installOnly?translateStatic('CARLA 설치 작업을 시작했습니다.'):translateStatic('CARLA 설치·실행 준비를 시작했습니다.'));}
async function stopLocalCarla(){if(previewBusy())throw new Error(previewBlockReason());if(active()?.kind==='collection')throw new Error(translateStatic('수집 작업을 먼저 중지한 뒤 CARLA를 종료하세요.'));const l=state.carla_local||{},taskRunning=l.task?.status==='Running';if(!taskRunning&&!(l.engine?.running&&l.engine?.owned))throw new Error(translateStatic('이 화면에서 관리 중인 CARLA 작업이나 엔진이 없습니다.'));if(!await confirmAction(taskRunning?translateStatic('CARLA 준비 작업을 중지할까요?'):translateStatic('CARLA 엔진을 종료할까요?'),taskRunning?translateStatic('진행 중인 다운로드·설치 또는 엔진 준비에 중지를 요청합니다. 실제 종료 상태가 확인될 때까지 진행 상태가 표시됩니다.'):translateStatic('이 화면에서 시작한 CARLA 엔진에 종료를 요청합니다. 종료 후 다시 실행할 수 있습니다.'),translateStatic('중지 요청'),'',true))return;const result=await api('/api/carla/local/stop','POST');adopt({carla_local:result.carla_local||result});renderLive();toast(translateStatic('CARLA 중지를 요청했습니다.'));}
async function refreshLocalCarlaLogs(){const data=await api('/api/carla/local/logs');const target=document.querySelector('#carla-local-log');if(target){const atBottom=target.scrollTop+target.clientHeight>=target.scrollHeight-30;target.textContent=data.text||translateStatic('아직 기록된 설치·엔진 로그가 없습니다.');if(atBottom)target.scrollTop=target.scrollHeight;}return data.text;}
async function showLocalCarlaLogs(){const dlg=document.querySelector('#confirm-dialog');document.querySelector('#dialog-title').textContent=translateStatic('CARLA 설치 · 엔진 로그');document.querySelector('#dialog-message').textContent=translateStatic('다운로드, 설치와 실제 엔진 프로세스의 출력 기록입니다.');document.querySelector('.dialog-icon').innerHTML=icon('terminal');document.querySelector('#dialog-detail').innerHTML=ui`<div class="local-log-tools">${button(translateStatic('로그 새로고침'),'carla-local-log-refresh','subtle small','refresh')}</div><pre class="log-panel" id="carla-local-log" style="padding:12px 0">로그를 불러오고 있습니다.</pre>`;document.querySelector('#dialog-confirm').textContent=translateStatic('닫기');document.querySelector('#dialog-confirm').className='button primary';dlg.showModal();try{await refreshLocalCarlaLogs();}catch(error){const target=document.querySelector('#carla-local-log');if(target)target.textContent=error.message;}}
function settings(){const s=state.settings;return ui`${diagnosticsHTML()}<div id="settings-lock-notice">${settingsLockNotice()}</div><div class="grid main-aside"><form id="settings-form" class="stack"><section class="panel"><div class="panel-head"><h2>프로젝트 · CARLA 서버</h2>${icon('server')}</div><div class="form-section"><div class="form-grid">${field('project_name',translateStatic('프로젝트 이름'),s.project_name,{cls:'span-all',required:true})}${field('carla_host',translateStatic('CARLA 호스트'),s.carla_host,{hint:translateStatic('URL 대신 IP 또는 호스트 이름'),required:true})}${field('carla_port',translateStatic('CARLA 포트'),s.carla_port,{type:'number',min:1,max:65535,step:1,required:true})}${field('carla_tm_port',translateStatic('Traffic Manager 포트'),s.carla_tm_port,{type:'number',min:1,max:65535,step:1,hint:translateStatic('CARLA 포트와 다른 값을 사용하세요.')})}${field('carla_install_path','CARLA 기존 설치 경로 (비우면 프로젝트 carla/)',s.carla_install_path||'',{hint:'기존 설치를 재사용합니다. 자동 덮어쓰기·재설치 없음.'})}<div class="field"><label>CARLA 렌더링 프로파일</label><select name="carla_render_profile">${[['offscreen','Off-screen · Epic (검증 기본)'],['windowed','Window · Epic'],['low','Window · Low (지도 전환 크래시 주의)'],['low_offscreen','Off-screen · Low (크래시 주의)']].map(([k,v])=>`<option value="${k}" ${s.carla_render_profile===k?'selected':''}>${v}</option>`).join('')}</select><small>변경은 다음 엔진 실행부터 반영됩니다. 데이터셋 Metadata에 기록합니다.</small></div></div></div></section><section class="panel"><div class="panel-head"><h2>데이터 · 결과 저장 경로</h2>${icon('folder')}</div><div class="form-section"><p>경로는 프로젝트 폴더 기준입니다. 기존 파일을 자동으로 이동하거나 삭제하지 않습니다.</p><div class="form-grid">${[['data_root',translateStatic('수집 데이터')],['train_data',translateStatic('학습 데이터')],['val_data',translateStatic('검증 데이터')],['test_tensor',translateStatic('미리보기 테스트 텐서 (선택)')],['sensor_config',translateStatic('학습 센서 보정 설정')],['results_root',translateStatic('모델 · 실험 결과')],['logs_root',translateStatic('실행 로그')]].map(([key,label])=>field(key,label,s[key],{required:true,hint:key==='test_tensor'?translateStatic('없으면 검증 데이터의 첫 샘플로 미리보기를 생성합니다.'):key==='sensor_config'?translateStatic('데이터 수집 당시의 sensor_config.yaml 경로'):''})).join('')}</div></div></section><section class="panel"><div class="panel-head"><h2>연구 실행 환경</h2>${icon('terminal')}</div><div class="form-section">${field('python_executable',translateStatic('Python 실행 파일'),s.python_executable,{hint:translateStatic('CARLA / PyTorch가 설치된 Python 실행 파일의 절대 경로'),required:true})}<div id="settings-feedback" class="inline-feedback"></div></div><div class="setting-actions"><button class="button primary" type="submit">${icon('save')}시스템 설정 저장</button></div></section></form><div class="stack"><div data-carla-local class="carla-local-mount compact">${localCarlaCard()}</div>${panel(translateStatic('환경 종속성'),`<div class="panel-body" id="environment-info">${dependenciesHTML()}</div>`,button(translateStatic('다시 검사'),'refresh-environment','subtle small','refresh'))}${panel(translateStatic('시스템 리소스'),`<div class="panel-body" id="resource-monitor"></div>`)}${panel(translateStatic('작업 오류 · 로그'),`<div id="system-job-list"></div>`)}</div></div>`;}
function dependenciesHTML(){const deps=state.capabilities.dependencies||{};const names=Object.keys(deps);return ui`${names.length?`<div class="environment-list">${names.map(name=>{const d=deps[name];return `<div class="environment-item"><span>${esc(name)}</span>${badge(d.available?'Completed':'warning',d.available?d.version||translateStatic('설치됨'):translateStatic('미설치'))}</div>`;}).join('')}</div>`:translateStatic('<p class="dependency-hint">의존성 검사 결과를 아직 수신하지 못했습니다.</p>')}<div class="keyvalue spaced"><dt>CUDA</dt><dd>${state.capabilities.cuda_available===true?badge('Completed',translateStatic('사용 가능')):state.capabilities.cuda_available===false?badge('warning',translateStatic('사용 불가')):translateStatic('검사 전')}</dd></div>${state.capabilities.warnings?.length?`<p class="dependency-hint">${state.capabilities.warnings.map(esc).join('<br>')}</p>`:''}<p class="dependency-hint spaced">전체 연구 의존성 설치 방법은 README를 확인하세요. 웹 관리 화면은 CARLA와 GPU 없이 실행할 수 있습니다.</p>`;}
function preflightHTML(kind){const p=state.preflight[kind],running=active(),dirty=state[`${kind}Dirty`];if(kind==='training'&&modelSelectionBlocker())return alertBox(esc(modelSelectionBlocker()),'error',translateStatic('모델 실행 환경을 확인하세요'));if(kind==='training'&&state.trainingOptionsError)return alertBox(esc(state.trainingOptionsError),'error',translateStatic('학습 데이터 확인이 필요합니다'));if(kind==='training'&&state.trainingOptionsPending)return `<div class="alert prerequisite-blocked">${icon('database')}<div>${translateStatic('학습·검증 파일과 센서별 라벨을 확인하고 있습니다.')}</div></div>`;if(previewBusy())return `<div class="alert prerequisite-blocked">${icon('camera')}<div><strong>${previewStatusLabel()}</strong>${translateStatic('센서 프리뷰를 중지하면 연구 작업을 시작할 수 있습니다.')} <a href="#simulation" data-action="open-sensor-preview" class="text-link">${translateStatic('센서 구성으로 이동')}</a></div></div>`;if(state.carla_local?.task?.status==='Running')return ui`<div class="alert prerequisite-blocked">${icon('server')}<div><strong>CARLA 설치·실행 준비 중</strong>준비 작업이 완료되거나 중지된 후 연구 작업을 시작할 수 있습니다. <a href="#simulation" data-action="open-local-carla" class="text-link">진행 상황 확인</a></div></div>`;if(dirty)return ui`<div class="alert prerequisite-blocked">${icon('save')}<div>변경한 설정을 저장한 뒤 준비 상태를 다시 확인하세요.</div></div>`;if(running&&kind!=='training')return ui`<div class="alert prerequisite-blocked">${icon('activity')}<div>${esc(running.name)} 작업이 실행 중입니다. 작업이 종료되면 새 실험을 시작할 수 있습니다.</div></div>`;if(!p)return ui`<p class="dependency-hint">준비 상태를 확인하고 있습니다.</p>`;if(p.ready)return ui`<div class="alert info ready">${icon('check')}<div><strong>실행 준비 완료</strong>현재 저장된 설정으로 작업을 시작할 수 있습니다.</div></div>`;return ui`<div class="alert prerequisite-blocked"><div>${icon('alert')}</div><div><strong>실행 전에 확인이 필요합니다</strong>${language==='en'?'<p class="small">Server details below are preserved in their original language.</p>':''}<ul>${(p.blockers||[]).map(b=>`<li>${esc(typeof b==='string'?b:b.message||JSON.stringify(b))}</li>`).join('')}</ul></div></div>`;}
function renderLive(){updateTop();updateDriving();document.querySelectorAll('[data-carla-local]').forEach(el=>{const sourceOpen=el.querySelector('.local-source')?.open;el.innerHTML=localCarlaCard();if(sourceOpen)el.querySelector('.local-source').open=true;});const put=(id,value)=>{const el=document.getElementById(id);if(el)el.innerHTML=value;};put('dashboard-stats',dashboardStats());put('collection-progress',collectionProgressHTML());put('driving-runtime-info',drivingTelemetryHTML(latest('collection')));put('current-operation',operationHTML(active()));put('current-badge',active()?badge(active().status):previewBusy()?badge('Running',previewStatusLabel()):badge('Idle'));put('recent-experiments',experimentTable(state.experiments.slice(0,4)));put('research-checklist',researchChecklist());put('system-notices',noticeHTML());put('resource-monitor',resourceHTML());put('carla-badge',badge(state.carla.connected?'connected':'Idle',state.carla.connected?translateStatic('서버 연결됨'):translateStatic('연결 대기')));put('carla-map',esc(state.carla.map||'—'));put('carla-state',state.carla.connected?translateStatic('연결됨'):translateStatic('연결되지 않음'));put('carla-actions',state.carla.connected?button(translateStatic('연결 해제'),'carla-disconnect','subtle','disconnect',previewBusy()?`disabled title="${esc(previewBlockReason())}"`:active()?.kind==='collection'?translateStatic('disabled title="수집 작업을 먼저 종료하세요."'):''):button(translateStatic('CARLA 연결'),'carla-connect','primary','link'));const event=latest('collection')?.last_event;if(event&&finite(event.speed_kmh))state.telemetry=event;const telemetry=state.liveFrame&&liveSceneJob===latest('collection')?.id?{speed_kmh:state.liveScene?.ego?.speed_kmh,town:state.liveScene?.environment?.map_name,sample:state.liveFrame.frame_key}:{};put('collection-telemetry', [[translateStatic('현재 속도'),finite(telemetry.speed_kmh)?`${num(telemetry.speed_kmh,1)} km/h`:'—'],[translateStatic('수집 타운'),telemetry.town||'—'],[translateStatic('저장 프레임'),telemetry.sample||'—']].map(([k,v])=>`<div><span>${k}</span><strong>${esc(v)}</strong></div>`).join(''));put('collection-scene-info',sceneInformationHTML((liveSceneJob===latest('collection')?.id?state.liveScene:null)||{},'live'));put('carla-message',state.carla.error?`<span class="error-text">${esc(state.carla.error)}</span>`:'');for(const kind of ['collection','training']){put(`${kind}-preflight`,preflightHTML(kind));const b=document.getElementById(`start-${kind}`);if(b){b.disabled=b.dataset.actionBusy==='1'||!state.online||(kind!=='training'&&!state.preflight[kind]?.ready)||(kind==='training'&&(state.trainingOptionsPending||Boolean(state.trainingOptionsError)||Boolean(modelSelectionBlocker())))||(kind!=='training'&&Boolean(active()))||previewBusy()||state.carla_local?.task?.status==='Running'||(kind!=='training'&&Boolean(state[`${kind}Dirty`]));b.title=previewBusy()?previewBlockReason():state.carla_local?.task?.status==='Running'?translateStatic('CARLA 설치·실행 준비가 끝난 후 연구 작업을 시작할 수 있습니다.'):b.disabled?translateStatic('설정을 저장하고 위의 실행 조건을 확인하세요.'):'';}const job=latest(kind);put(`${kind}-current`,job?ui`<div class="spaced"><div class="keyvalue"><dt>최근 작업</dt><dd>${badge(job.status)}</dd></div><div class="path-text">${esc(job.name)}</div></div>`:'');}const train=latest('training');put('training-job',train?jobCard(train):empty('training',translateStatic('아직 시작한 학습이 없습니다'),translateStatic('모델과 데이터를 설정한 후 학습을 시작하세요.'),button(translateStatic('학습 설정 열기'),'train-tab','subtle small','settings','data-tab="setup"')));put('training-summary',trainingSummary(train));put('training-pretrained',pretrainedHTML());put('training-checkpoints',checkpointHTML(train));put('training-history',jobList(state.jobs.filter(j=>j.kind==='training').slice(0,5)));renderBestMetrics();renderQueue();refreshPredictionGallery('training');put('system-job-list',jobList(state.jobs.filter(j=>j.status==='Failed'||j.status==='Stopped').slice(0,5)));document.querySelectorAll('#settings-form input,#settings-form button[type=submit],#collection-form button[type=submit],#training-form button[type=submit],#dataset-form button[type=submit]').forEach(el=>{const isConnectionField=el.closest('#settings-form')&&['carla_host','carla_port','python_executable'].includes(el.name);if((active()&&!el.closest('#training-form'))||(isConnectionField&&localConnectionLocked())){el.dataset.jobLocked='1';el.disabled=true;if(isConnectionField&&previewBusy()){el.title=previewBlockReason();el.dataset.previewLocked='1';}}else if(el.dataset.jobLocked){el.disabled=false;delete el.dataset.jobLocked;}if(el.dataset.previewLocked&&!previewBusy()){el.removeAttribute('title');delete el.dataset.previewLocked;}});put('settings-lock-notice',settingsLockNotice());renderTrainingChart();renderModelAvailability();window.SensorPreview?.update(state);syncPanelFolds();scheduleCollectionPreview();}
function jobList(jobs){return jobs.length?`<ul class="file-list">${jobs.map(j=>ui`<li>${icon(j.kind==='training'?'training':'simulation')}<div class="file-main">${esc(j.name)}<small>${stamp(j.created_at)}</small></div><button class="text-link" data-action="job-logs" data-id="${esc(j.id)}" title="작업 로그 보기">${badge(j.status)}</button></li>`).join('')}</ul>`:empty('clock',translateStatic('작업 기록이 없습니다'),translateStatic('작업 실행 후 상태와 로그가 표시됩니다.'));}
const preflightRequests={collection:0,training:0};
async function checkPreflight(kind,silent=false,prepareWeights=!silent){const request=(preflightRequests[kind]||0)+1;preflightRequests[kind]=request;try{const result=await api('/api/preflight','POST',{kind,prepare_weights:kind==='training'&&prepareWeights,...(kind==='training'?{allow_busy:true,settings:{train_data:trainingOptionsDraft().train_data,val_data:trainingOptionsDraft().val_data}}: {})});if(preflightRequests[kind]!==request)return state.preflight[kind]||result;state.preflight[kind]=result;if(result.pretrained)receivePretrained(result.pretrained);if(!silent)toast(result.ready?translateStatic('실행 준비가 완료되었습니다.'):translateStatic('실행에 필요한 항목을 확인하세요.'),!result.ready);renderLive();return result;}catch(error){if(preflightRequests[kind]!==request)return state.preflight[kind]||{ready:false,blockers:[error.message]};state.preflight[kind]={ready:false,blockers:[error.message]};renderLive();if(!silent)toast(error.message,true);return state.preflight[kind];}}

async function refresh(quiet=false){const data=await api('/api/status');adopt(data);renderLive();if(!quiet)toast(translateStatic('실제 작업 상태를 갱신했습니다.'));}
async function refreshCatalog(rerender=true){const [experiments,datasets]=await Promise.all([api('/api/experiments'),api('/api/datasets')]);state.experiments=arr(experiments,'experiments');state.datasets=arr(datasets,'datasets');if(rerender){if(['results','simulation'].includes(state.route))render();else renderLive();}}
async function loadLogs(kind='training',id=null){const job=id?state.jobs.find(j=>j.id===id):latest(kind);if(!job)return;const [result,detail]=await Promise.all([api(`/api/jobs/${encodeURIComponent(job.id)}/logs`),api(`/api/jobs/${encodeURIComponent(job.id)}`)]);state.jobDetails[job.id]=detail;if(kind==='training'){renderTrainingChart();renderBestMetrics();renderLiveTrainingProgress();}const text=result.text??result.logs??'';const node=document.querySelector(`#${kind}-log`);if(node){const atBottom=node.scrollTop+node.clientHeight>=node.scrollHeight-35;node.textContent=text||translateStatic('아직 출력된 로그가 없습니다.');if(atBottom)node.scrollTop=node.scrollHeight;}return text;}
function feedback(id,message,ok){const el=document.querySelector(`#${id}`);if(el){el.textContent=message;el.className=`inline-feedback ${ok?'good':'bad'}`;}}
function formData(id){const form=document.getElementById(id);if(!form||!form.reportValidity())throw new Error(translateStatic('입력값을 확인하세요.'));return new FormData(form);}
async function saveCollection(){if(active())throw new Error(translateStatic('실행 중인 작업을 완료하거나 중지한 후 수집 설정을 저장하세요.'));const data=formData('collection-form');const sensors={...structuredClone(state.sensors),data_num:Number(data.get('data_num')),towns:['Town01','Town02','Town03','Town04','Town05','Town06','Town07','Town10HD'].filter(t=>data.has(`town_${t}`))};const setting=Object.fromEntries(['vehicle','weather','npc_vehicles','npc_walkers','fps','preview_fps'].map(k=>[k,['vehicle','weather'].includes(k)?data.get(k):Number(data.get(k))]));setting.bev_generator=readBevSettings(data,state.settings.bev_generator);setting.driving=readDrivingSettings(data);try{state.sensors=await api('/api/config/sensors','PUT',sensors);state.settings=await api('/api/settings','PUT',setting);state.collectionDirty=false;feedback('collection-feedback',translateStatic('수집 환경과 센서 설정을 저장했습니다.'),true);await checkPreflight('collection',true);return true;}catch(error){feedback('collection-feedback',error.message,false);throw error;}}
async function saveSensors(){const data=formData('sensor-form'),sensors={};for(const name of Object.keys(sensorNames)){if(!data.has(`enable_${name}`))continue;sensors[name]={};const defaults=state.sensors.sensors?.[name]||sensorDefaults(name);for(const key of Object.keys(defaults))sensors[name][key]=['seg','depth','od'].includes(key)?data.has(`${name}.${key}`):Number(data.get(`${name}.${key}`));}try{state.sensors=await api('/api/config/sensors','PUT',{...state.sensors,sensors});state.collectionDirty=false;feedback('sensor-feedback',translateStatic('센서 구성을 저장했습니다.'),true);await checkPreflight('collection',true);toast(translateStatic('센서 구성을 저장했습니다.'));}catch(error){feedback('sensor-feedback',error.message,false);throw error;}}
async function saveTraining(){const payload=await trainingDraftPayload();try{state.training=await api('/api/config/training','PUT',payload.config);state.settings=await api('/api/settings','PUT',payload.settings);state.trainingDirty=false;await refreshTrainingOptions();feedback('training-feedback',translateStatic('다음 학습에 사용할 설정을 저장했습니다. 실행 중인 작업의 설정은 유지됩니다.'),true);await checkPreflight('training',true);return true;}catch(error){feedback('training-feedback',error.message,false);throw error;}}
async function saveSettings(){const d=formData('settings-form'),s=Object.fromEntries(d.entries());for(const k of ['carla_port','carla_tm_port'])if(k in s)s[k]=Number(s[k]);try{state.settings=await api('/api/settings','PUT',s);if(drafts['training-form'])for(const key of ['train_data','val_data'])if(drafts['training-form'][key])drafts['training-form'][key].value=state.settings[key];feedback('settings-feedback',translateStatic('시스템 설정을 저장했습니다. 다음 작업부터 반영됩니다.'),true);await refreshModelEnvironment();await refreshTrainingOptions();await Promise.all([checkPreflight('collection',true),checkPreflight('training',true)]);toast(translateStatic('시스템 설정을 저장했습니다.'));updateTop();}catch(error){feedback('settings-feedback',error.message,false);throw error;}}
async function startJob(kind){if(kind==='training')return enqueueTraining();if(previewBusy())throw new Error(previewBlockReason());if(state.carla_local?.task?.status==='Running')throw new Error(translateStatic('CARLA 설치·실행 준비가 끝나거나 중지된 후 연구 작업을 시작하세요.'));if(active())return toast(translateStatic('실행 중인 작업을 먼저 종료하세요.'),true);if(kind==='collection'&&document.querySelector('#collection-form'))await saveCollection();if(kind==='training'&&document.querySelector('#training-form'))await saveTraining();const preflight=await checkPreflight(kind,true,kind==='training');if(!preflight.ready)return toast(translateStatic('실행 준비 항목을 확인하세요.'),true);const isTraining=kind==='training';const name=document.querySelector(`#${kind}_name`)?.value||'';const detail=isTraining?ui`<div class="keyvalue"><dt>모델</dt><dd>${esc(state.training.model?.encoder)} / ${esc(state.training.model?.decoder)}</dd></div><div class="keyvalue"><dt>Epoch / Batch</dt><dd>${esc(state.training.Epochs)} / ${esc(state.training.batch)}</dd></div>`:ui`<div class="keyvalue"><dt>수집 타운</dt><dd>${state.sensors.towns.map(esc).join(', ')}</dd></div><div class="keyvalue"><dt>타운당 샘플</dt><dd>${num(state.sensors.data_num)}</dd></div>`;const accepted=await confirmAction(isTraining?translateStatic('모델 학습을 시작할까요?'):translateStatic('데이터 수집을 시작할까요?'),isTraining?translateStatic('저장된 설정으로 실제 Python 학습 작업을 실행합니다. 페이지 이동이나 새로고침 후에도 학습은 계속됩니다.'):translateStatic('선택한 맵을 불러오면서 CARLA의 현재 월드가 변경됩니다. 다른 실험이 없는 전용 CARLA 세션인지 확인하세요. 수집은 별도 Python 프로세스로 실행됩니다.'),isTraining?translateStatic('학습 시작'):translateStatic('수집 시작'),detail);if(!accepted)return;const job=await api('/api/jobs','POST',{kind,name});state.jobs=[job,...state.jobs.filter(j=>j.id!==job.id)];if(isTraining)state.trainTab='monitor';else state.livePreview=true;render();toast(isTraining?translateStatic('모델 학습 작업을 시작했습니다.'):translateStatic('데이터 수집 작업을 시작했습니다.'));}
