let collectionPreviewTimer=null,collectionPreviewPending=false;
function collectionPreviewEnabled(){return state.route==='simulation'&&state.simTab==='collect'&&state.livePreview&&state.online&&!document.hidden;}
function scheduleCollectionPreview(delay){if(!collectionPreviewEnabled()){clearTimeout(collectionPreviewTimer);collectionPreviewTimer=null;return;}if(collectionPreviewTimer!==null||collectionPreviewPending)return;const fps=Number.isInteger(state.settings.preview_fps)?Math.max(1,Math.min(60,state.settings.preview_fps)):24;collectionPreviewTimer=setTimeout(async()=>{collectionPreviewTimer=null;let loaded=false;try{loaded=await refreshPreview();}finally{scheduleCollectionPreview(loaded?undefined:1000);}},delay??(latest('collection')?1000/fps:1000));}
