document.addEventListener('click',async event=>{const summary=event.target.closest('summary[data-fold-summary]');if(summary){const panel=summary.closest('details[data-fold]');rememberPanelChoice(panel.dataset.fold,!panel.open);return;}const link=event.target.closest('a[href^="/api/"]');if(link&&authToken()){event.preventDefault();try{const res=await authenticatedFetch(link.getAttribute('href'));if(!res.ok)throw new Error(translateStatic('파일을 내려받지 못했습니다. 접속 권한과 결과 파일을 확인하세요.'));const header=res.headers.get('content-disposition')||'';const match=/filename\*=UTF-8''([^;]+)|filename="?([^";]+)/i.exec(header);const name=match?decodeURIComponent(match[1]||match[2]):'sdv-export';const url=URL.createObjectURL(await res.blob());const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(error){toast(error.message,true);}return;}const el=event.target.closest('[data-action]');if(!el||el.disabled)return;const fn=actions[el.dataset.action];if(!fn)return;event.preventDefault();const wasDisabled=el.disabled;el.disabled=true;el.dataset.actionBusy='1';try{await fn(el);}catch(error){toast(error.message,true);}finally{delete el.dataset.actionBusy;if(el.isConnected)el.disabled=wasDisabled;}});
document.addEventListener('submit',async event=>{const form=event.target;if(!['collection-form','sensor-form','training-form','settings-form','dataset-form'].includes(form.id))return;event.preventDefault();const b=event.submitter;if(b)b.disabled=true;try{await ({'collection-form':saveCollection,'sensor-form':saveSensors,'training-form':saveTraining,'settings-form':saveSettings,'dataset-form':prepareDataset})[form.id]();if(['collection-form','training-form'].includes(form.id))toast(translateStatic('설정을 저장했습니다.'));}catch(error){toast(error.message,true);}finally{if(b?.isConnected)b.disabled=false;}});
document.addEventListener('change',async event=>{const el=event.target;try{if(el.id==='ui-language'){switchUILanguage(el.value);return;}if(el.dataset.compare){el.checked?state.selected.add(el.dataset.compare):state.selected.delete(el.dataset.compare);document.querySelector('#compare-count').textContent=ui`${state.selected.size}개 선택`;document.querySelector('#compare-button').disabled=state.selected.size<2;}if(el.closest('#training-form')){if(el.name?.startsWith('sensor_')||['train_data','val_data'].includes(el.name))await refreshTrainingOptions();if(el.name==='task_BEV'||el.name==='bev_decoder')syncBEVDecoder();if(['encoder','decoder','bev_decoder','task_BEV'].includes(el.name))renderLive();}if(el.id==='best-metric-split')renderBestMetrics();if(el.dataset.galleryFilter)changeGalleryFilter(el);if(el.id==='train-metric'){state.trainMetric=el.value;renderTrainingChart();}if(el.id==='result-metric'){state.metric=el.value;document.querySelector('#result-chart').innerHTML=chartHTML(state.detail.metrics.filter(m=>m.name===state.metric));}if(el.id==='compare-metric')renderCompareChart(el.value);if(el.id==='dataset-channel'){state.previewChannel=el.value;renderDatasetImage();}if(el.id==='live-preview'){state.livePreview=el.checked;scheduleCollectionPreview(0);}if(el.id==='preview-mode')refreshPreview();if(el.id==='settings-file'&&el.files?.[0]){const file=el.files[0];if(file.size>1048576)throw new Error(translateStatic('설정 파일은 1 MB 이하의 JSON이어야 합니다.'));const data=JSON.parse(await file.text());if(!data||typeof data!=='object'||Array.isArray(data))throw new Error(translateStatic('설정 JSON 객체를 선택하세요.'));const ok=await confirmAction(translateStatic('시스템 설정을 불러올까요?'),translateStatic('파일의 설정을 검증한 뒤 현재 시스템 설정에 적용합니다. 기존 데이터 파일은 이동하지 않습니다.'),translateStatic('불러오기'),ui`<div class="keyvalue"><dt>파일</dt><dd>${esc(file.name)}</dd></div>`);if(ok){state.settings=await api('/api/settings','PUT',data);delete drafts['settings-form'];document.querySelector('#settings-form')?.remove();await refreshModelEnvironment();await refreshTrainingOptions();await Promise.all([checkPreflight('collection',true),checkPreflight('training',true)]);render();toast(translateStatic('시스템 설정을 불러왔습니다.'));}el.value='';}}catch(error){toast(error.message,true);}});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='experiment-search'){const q=el.value.toLowerCase();document.querySelector('#experiment-list').innerHTML=experimentTable(state.experiments.filter(e=>String(e.name).toLowerCase().includes(q)),true);}const form=el.closest('form');if(form&&['collection-form','sensor-form','training-form'].includes(form.id)&&!el.name?.endsWith('_name')){const kind=form.id==='training-form'?'training':'collection';state[`${kind}Dirty`]=true;const b=document.querySelector(`#start-${kind}`);if(b&&kind!=='training')b.disabled=true;const pre=document.querySelector(`#${kind}-preflight`);if(pre)pre.innerHTML=preflightHTML(kind);}});
