let source,lastEvent=0,refreshPending=false,previewTick=0;
function connectEvents(){if(authToken())return;source=new EventSource('/api/events');source.addEventListener('status',event=>{try{const data=JSON.parse(event.data);adopt(data);lastEvent=Date.now();renderLive();}catch(error){console.warn('SDV status event:',error.message);}});source.onopen=()=>{state.online=true;updateTop();};source.onerror=()=>{state.online=false;updateTop();};}
async function boot(){try{const data=await api('/api/bootstrap');adopt(data);shell();render();restoreLanguageView();connectEvents();await Promise.all([checkPreflight('collection',true),checkPreflight('training',true),refreshLocalCarla(true)]);setInterval(async()=>{if(refreshPending||document.hidden)return;refreshPending=true;try{if(Date.now()-lastEvent>12000)await refresh(true);if(state.route==='training'&&state.trainTab==='monitor'){await loadLogs();await refreshPredictionGallery('training');}if(state.route==='training'&&state.trainTab==='queue')await refreshQueue();if(state.route==='simulation'&&state.simTab==='collect'){await loadLogs('collection');await refreshLiveScene();}if(document.querySelector('#confirm-dialog')?.open&&document.querySelector('#carla-local-log'))await refreshLocalCarlaLogs();if(++previewTick%6===0)await refreshCatalog(false);}catch(error){state.online=false;updateTop();}finally{refreshPending=false;}},3000);}catch(error){document.querySelector('#app').innerHTML=ui`<div class="boot-screen"><div class="brand-symbol">${icon('server')}</div><h1>서버에 연결할 수 없습니다</h1><p>${esc(error.message)}</p><p>프로젝트에서 start.sh를 실행한 뒤 다시 접속하세요.</p><button class="button primary" id="retry-boot">연결 다시 시도</button></div>`;document.querySelector('#retry-boot').onclick=boot;}}
boot();

// Training drafts never change the immutable configuration of a running job.
function optimizerName(config){return Object.keys(config?.opt_checkboxes||{}).find(key=>config.opt_checkboxes[key])||config?.optimizer||'—';}
function duration(value){const seconds=Math.max(0,Math.round(value||0));return seconds>=3600?ui`${Math.floor(seconds/3600)}시간 ${Math.floor(seconds%3600/60)}분`:seconds>=60?ui`${Math.floor(seconds/60)}분 ${seconds%60}초`:ui`${seconds}초`;}
function activeSeconds(job){return (finite(job.active_elapsed_seconds)?job.active_elapsed_seconds:0)+(['Running','Pausing'].includes(job.status)&&finite(job.segment_started_unix)?Math.max(0,Date.now()/1000-job.segment_started_unix):0);}
function trainingETA(job){if(!job||!['Running','Pausing'].includes(job.status))return null;if(finite(job.eta_remaining_seconds))return {remaining:job.eta_remaining_seconds,finish:Date.now()+job.eta_remaining_seconds*1000};const epochs=(job.metrics||[]).filter(event=>(event.event||event.type)==='training_epoch');const durations=epochs.map(event=>event.epoch_duration_sec??event.duration_seconds??event.duration_sec).filter(value=>finite(value)&&value>0);if(!durations.length)return null;const average=durations.slice(-5).reduce((sum,value)=>sum+value,0)/Math.min(5,durations.length),completed=job.last_completed_epoch??epochs.at(-1)?.epoch??0,total=job.progress_total??job.config?.Epochs;if(!finite(total)||total<=completed)return null;const last=epochs.at(-1),recordedAt=last?.timestamp??last?.time,spent=finite(recordedAt)?Math.max(0,Date.now()/1000-recordedAt):0;const remaining=Math.max(0,(total-completed)*average-Math.min(average,finite(job.segment_started_unix)?Math.max(0,Date.now()/1000-Math.max(job.segment_started_unix,finite(recordedAt)?recordedAt:job.segment_started_unix)):spent));return {remaining,finish:Date.now()+remaining*1000};}
