async function trainingDraftPayload(){await refreshTaskCatalog();if(document.querySelector('#task-advanced-settings')&&!state.taskCatalog)throw new Error(say('태스크별 데이터 클래스를 확인한 뒤 저장하세요.','Inspect the task classes before saving.'));if(!await refreshTrainingOptions())throw new Error(state.trainingOptionsError||translateStatic('학습 데이터 확인이 필요합니다'));if(modelSelectionBlocker())throw new Error(modelSelectionBlocker());const data=formData('training-form'),config=structuredClone(state.training);for(const key of ['Epochs','batch','LR','width','height'])config[key]=Number(data.get(key));config.model={...config.model,encoder:data.get('encoder'),decoder:data.get('decoder'),bev_decoder:data.has('task_BEV')?(data.get('bev_decoder')||state.bevDecoderChoice||'ResNet'):null};config.model_conf=Object.fromEntries(['BEV','Seg','Depth','od'].map(key=>[key,data.has(`task_${key}`)]));config.sensor_use=Object.fromEntries(trainingSensorIds.map(key=>[key,data.has(`sensor_${key}`)]));config.lidar=config.sensor_use.lidar;config.opt_checkboxes=Object.fromEntries(['Adam','AdamW','SGD'].map(key=>[key,data.get('optimizer')===key]));config.save_checkboxes={...config.save_checkboxes,Last_Epoch:data.has('save_Last_Epoch'),Best_Loss:data.has('save_Best_Loss')};config.task_settings=readAdvancedSettings();config.losses=readLossSettings(document.querySelector('#training-form'),state.training.losses);config.monitor={train_preview_every:Number(data.get('train_preview_every')),val_preview_every:Number(data.get('val_preview_every')),preview_samples:4,train_preview_basis:data.get('train_preview_basis'),preview_max_mib:Number(data.get('preview_max_mib'))};return {config,settings:{train_data:data.get('train_data'),val_data:data.get('val_data'),sensor_config:data.get('dataset_sensor_config')},name:data.get('training_name')||''};}
