function trainingQueue(){return `${panel(translateStatic('학습 대기열'),`<div class="queue-intro">${translateStatic('설정은 작업별로 고정됩니다. 대기 중인 작업만 순서를 변경할 수 있습니다. 일시정지는 현재 Epoch 완료 후 저장하고, 재개는 마지막 저장 Epoch 다음부터 진행합니다.')}</div><div id="training-queue-list"></div>`,button(translateStatic('새 모델 추가'),'train-tab','primary small','training','data-tab="setup"'))}<div id="queue-feedback" role="status" class="inline-feedback"></div>`;}
function queueJobs(){const jobs=state.jobs.filter(job=>job.kind==='training'&&!job.queue_removed&&job.status!=='Deleted');const ranking={Running:0,Pausing:0,Queued:1,Paused:2,Failed:3,Stopped:3,Completed:4};return jobs.sort((a,b)=>(ranking[a.status]??5)-(ranking[b.status]??5)||(a.status==='Queued'?(a.queue_position??999)-(b.queue_position??999):String(b.created_at||'').localeCompare(String(a.created_at||''))));}
function renderQueue(){const count=document.querySelector('[data-action="train-tab"][data-tab="queue"] .queue-count');if(count)count.textContent=state.jobs.filter(job=>job.kind==='training'&&!job.queue_removed&&['Queued','Running','Pausing','Paused'].includes(job.status)).length;const target=document.querySelector('#training-queue-list');if(!target)return;const jobs=queueJobs(),queued=jobs.filter(job=>job.status==='Queued');target.innerHTML=jobs.length?`<div class="table-wrap queue-table-wrap"><table class="training-queue-table"><thead><tr><th>${translateStatic('순서')}</th><th>${translateStatic('실험 / 모델')}</th><th>Optimizer · LR · Batch</th><th>${translateStatic('입력 / 태스크')}</th><th>${translateStatic('진행 / 상태')}</th><th>${translateStatic('제어')}</th></tr></thead><tbody>${jobs.map(job=>{const config=job.config||{},order=queued.findIndex(item=>item.id===job.id),eta=trainingETA({...state.jobDetails[job.id],...job,metrics:state.jobDetails[job.id]?.metrics||job.metrics});return `<tr data-queue-job="${esc(job.id)}"><td>${job.status==='Queued'?`<div class="queue-order"><strong>${order+1}</strong><div>${button('↑','queue-up','subtle small','',`data-id="${esc(job.id)}" ${order===0?'disabled':''} aria-label="${translateStatic('위로 이동')}"`)}${button('↓','queue-down','subtle small','',`data-id="${esc(job.id)}" ${order===queued.length-1?'disabled':''} aria-label="${translateStatic('아래로 이동')}"`)}</div></div>`:['Running','Pausing'].includes(job.status)?icon('play'):'—'}</td><td><button class="table-link" data-action="queue-monitor" data-id="${esc(job.id)}"><strong>${esc(job.name||job.id)}</strong></button><small>${esc(config.model?.encoder||'—')} / ${esc(config.model?.decoder||'—')}<br>BEV ${esc(config.model?.bev_decoder||'None')}</small><small class="queue-data-path" title="${esc(job.settings?.val_data||'')}">${esc(job.settings?.val_data||'')}</small></td><td><strong>${esc(optimizerName(config))}</strong><small>LR ${esc(config.LR??'—')} · Batch ${num(config.batch)}</small></td><td class="queue-task-cell"><span>${esc(Object.keys(config.sensor_use||{}).filter(key=>config.sensor_use[key]).join(', ')||'—')}</span><small>${esc(Object.keys(config.model_conf||{}).filter(key=>config.model_conf[key]).join(', ')||'—')}</small></td><td>${badge(job.status)}<small>Epoch ${num(job.last_completed_epoch??job.progress_current??0)} / ${num(job.progress_total??config.Epochs)}</small>${eta?`<small>${translateStatic('예상 남은 시간')} ${duration(eta.remaining)}</small>`:''}${job.status==='Pausing'?`<small class="queue-note">${translateStatic('현재 Epoch 완료 후 저장')}</small>`:''}${job.blocked_reason?.length?`<small class="error-text">${esc((Array.isArray(job.blocked_reason)?job.blocked_reason:[job.blocked_reason]).map(reason=>typeof reason==='string'?reason:reason.message||JSON.stringify(reason)).join(' · '))}</small>`:''}</td><td><div class="queue-controls">${button(translateStatic('모니터링'),'queue-monitor','subtle small','activity',`data-id="${esc(job.id)}"`)}${job.status==='Running'?button(translateStatic('일시정지'),'pause-job','subtle small','clock',`data-id="${esc(job.id)}"`):stoppedTrainingActions(job,true)}${['Running','Pausing'].includes(job.status)?button(translateStatic('중지'),'stop-job','danger small','stop',`data-id="${esc(job.id)}" ${job.stop_requested?'disabled':''}`):button(translateStatic('대기열에서 삭제'),'delete-job','subtle small','close',`data-id="${esc(job.id)}"`)}</div></td></tr>`;}).join('')}</tbody></table></div>`:empty('layers',translateStatic('학습 대기열이 비어 있습니다'),translateStatic('모델과 데이터를 설정하고 학습 대기열에 추가하세요.'),button(translateStatic('새 모델 추가'),'train-tab','primary small','training','data-tab="setup"'));}
let queueRequest=0;
async function refreshQueue(){const request=++queueRequest;try{const result=await api('/api/training/queue');if(request!==queueRequest)return;const jobs=arr(result,'jobs');for(const job of jobs)state.jobs=[...state.jobs.filter(item=>item.id!==job.id),job];state.queue=jobs;renderQueue();}catch(error){feedback('queue-feedback',error.message,false);}}
