async function resumeTraining(id){const result=await api(`/api/jobs/${encodeURIComponent(id)}/resume`,'POST');state.jobs=state.jobs.map(job=>job.id===id?{...job,...result}:job);await refreshQueue();renderLive();toast(translateStatic('저장된 Checkpoint에서 재개하도록 대기열에 추가했습니다.'));}
async function deleteTraining(id){if(!await confirmAction(translateStatic('대기열에서 삭제할까요?'),translateStatic('작업을 대기열에서 제거합니다. 이미 저장된 실험 결과·Prediction·Checkpoint 파일은 유지됩니다.'),translateStatic('대기열에서 삭제'),'',true))return;const result=await api(`/api/jobs/${encodeURIComponent(id)}`,'DELETE');state.jobs=state.jobs.map(job=>job.id===id?{...job,...result,queue_removed:true}:job);await refreshQueue();renderQueue();toast(translateStatic('대기열에서 제거했습니다. 저장된 결과는 실험 기록에서 확인할 수 있습니다.'));}
function metricInfo(series){const registry=(state.route==='results'?state.detail?.metric_registry:latest('training')?.metric_registry)||state.metric_registry||{},row=registry[`${series.split}_${series.name}`]||registry[series.name]||{},name=series.name.toLowerCase();const short={seg_miou:'mIoU',seg_mdice:'mDice',seg_mean_dice:'mDice',seg_pixel_accuracy:'Pixel Accuracy',depth_abs_rel:'AbsRel',depth_rmse:'RMSE',depth_mae:'MAE',depth_delta1:'δ1',od_map_50:'mAP@0.5',od_map_50_95:'mAP@0.5:0.95'};let label=short[name]||row.label||metricLabel(series.name);const match=/^seg_class_(\d+)_(iou|dice)$/i.exec(series.name);if(match&&!row.label){const config=(state.route==='results'?experimentConfig(state.detail||{}):latest('training')?.config)||state.training,classes=config.task_settings?.segmentation?.class_ids||[],entry=classes[Number(match[1])],className=entry?.name||(state.taskCatalog?.segmentation?.classes||state.taskCatalog?.seg?.classes||[]).find(c=>c.id==entry)?.name;label=`${className||row.class_name||say('매핑 정보 없는 클래스','Unmapped class')+' '+match[1]} ${match[2]==='iou'?'IoU':'Dice'}`;}const direction=row.direction||(/loss|rmse|mae|abs_rel|sq_rel/i.test(name)?'min':/iou|dice|accuracy|precision|recall|f1|map|delta/i.test(name)?'max':null),maximum=row.maximum!==undefined?row.maximum:row.upper_bound!==undefined?row.upper_bound:row.unit==='%'||row.unit==='percent'?100:/iou|dice|accuracy|precision|recall|f1|map|delta/i.test(name)?1:null;return {...row,label,task:row.task||(/^(seg|depth|od|bev)/i.exec(series.name)?.[1]||translateStatic('공통')),direction,maximum,detail:row.detail===true||/class_\d+|legacy|valid_pixels|pixels/i.test(name)||['seg_iou','od_iou'].includes(name)};}
function bestMetricTable(series,split='val',globalBest={},selectedEpoch=null){const candidates=series.filter(item=>item.split===split&&(item.x_label||'epoch')==='epoch');for(const [key,best] of Object.entries(globalBest)){const prefix=split+'_';if(key.startsWith(prefix)&&!candidates.some(item=>item.name===key.slice(prefix.length)))candidates.push({name:key.slice(prefix.length),split,x_label:'epoch',points:[],best});}const rows=candidates.map(item=>{const info=metricInfo(item),points=(item.points||[]).filter(point=>finite(point.x)&&finite(point.y)),direction=info.direction;if(!['min','max'].includes(direction)||info.unit==='pixels')return null;const stored=globalBest[`${split}_${item.name}`]||item.best,best=finite(stored?.value)&&finite(stored?.epoch)?{x:stored.epoch,y:stored.value}:points.length?(direction==='min'?points.reduce((a,b)=>b.y<a.y?b:a):points.reduce((a,b)=>b.y>a.y?b:a)):null;if(!best&&!points.length)return null;return {item,info,best,current:selectedEpoch===null?points.at(-1):points.find(point=>point.x===selectedEpoch)};}).filter(Boolean).sort((a,b)=>a.info.task.localeCompare(b.info.task)||a.info.label.localeCompare(b.info.label));const table=list=>`<div class="table-wrap best-metrics-wrap"><table class="best-metrics-table"><thead><tr><th>${translateStatic('태스크')}</th><th>Metric</th><th>Current${selectedEpoch===null?'':` · E${selectedEpoch}`}</th><th>Best</th><th>Best Epoch</th><th>Maximum</th></tr></thead><tbody>${list.map(({info,best,current})=>`<tr><td>${esc(info.task)}</td><td title="${info.direction==='min'?translateStatic('낮을수록 좋음'):translateStatic('높을수록 좋음')}">${esc(info.label)} <span class="metric-direction">${info.direction==='min'?'↓':'↑'}</span></td><td>${metricValue(current?.y)}</td><td class="best-value">${metricValue(best?.y)}</td><td>${best?num(best.x):'—'}</td><td>${finite(info.maximum)?metricValue(info.maximum):'None'}</td></tr>`).join('')}</tbody></table></div>`;return rows.length?`${table(rows.filter(row=>!row.info.detail))}${rows.some(row=>row.info.detail)?`<details class="metric-details"><summary>${say('클래스별 지표 · 상세 보기','Per-class metrics · Details')}</summary>${table(rows.filter(row=>row.info.detail))}</details>`:''}<div class="panel-foot">${say('Maximum은 지표의 이론적 상한입니다. Best는 실제 전체 기록이며, 값 위에 커서를 두면 원래 정밀도를 확인할 수 있습니다.','Maximum is the theoretical bound. Best uses the full recorded history. Hover a value for its original precision.')}</div>`:empty('results',translateStatic('기록된 성능 지표가 없습니다'),translateStatic('Epoch가 완료되면 실제 태스크 지표와 Best 값을 표시합니다.'));}
function renderBestMetrics(){const target=document.querySelector('#training-best-metrics');if(target){const expanded=target.querySelector('.metric-details')?.open;target.innerHTML=bestMetricTable(metricsFromJob(latest('training')),document.querySelector('#best-metric-split')?.value||'val',latest('training')?.best_metrics||{},selectedMonitorEpoch());if(expanded&&target.querySelector('.metric-details'))target.querySelector('.metric-details').open=true;}renderEpochMetricStrip();}

// Saved predictions are read from the actual research output. Images use the same
