const galleryFilters={training:{split:'val',epoch:'latest',time_mode:'epoch',sample_id:'',task:''},result:{split:'val',epoch:'latest',time_mode:'epoch',sample_id:'',task:''}};
const galleryRequests={};
function galleryOwner(namespace){return namespace==='training'?latest('training')?.id:state.detail?.id;}
function galleryAPI(namespace,id){return `/api/${namespace==='training'?'jobs':'experiments'}/${encodeURIComponent(id)}/predictions`;}
function predictionGalleryShell(namespace,id){return `<section class="panel prediction-gallery timeline-gallery" id="${namespace}-predictions" data-gallery-owner="${esc(id)}"><div class="panel-head"><div><span class="eyebrow">PREDICTION TIMELINE</span><h2>${translateStatic('Prediction 기록')}</h2><p>${translateStatic('VAL은 같은 데이터셋에서 고정한 최대 4개 샘플을 비교합니다. TRAIN은 설정한 Step 간격으로 저장합니다.')}</p></div>${button(translateStatic('새로고침'),'gallery-refresh','subtle small','refresh',`data-gallery="${namespace}"`)}</div><div class="prediction-toolbar" id="${namespace}-prediction-filters"></div><div class="prediction-dataset-note" id="${namespace}-prediction-note"></div><div class="prediction-sample-tabs" id="${namespace}-prediction-samples"></div><div class="prediction-epoch-metrics" id="${namespace}-epoch-metrics"></div><div class="prediction-scroll" id="${namespace}-prediction-entries">${empty('camera',translateStatic('저장된 Prediction이 없습니다'),translateStatic('학습·검증을 진행하면 실제 입력·정답·Prediction 이미지가 여기에 표시됩니다.'))}</div><div id="${namespace}-prediction-timeline"></div><div id="${namespace}-prediction-pagination"></div></section>`;}
function galleryFilterQuery(namespace,data){
 const filter=galleryFilters[namespace],query=new URLSearchParams({limit:'200',offset:'0'});if(filter.split)query.set('split',filter.split);
 const timeline=data?.timeline||[],epochs=[...new Set(timeline.map(item=>item.epoch))].filter(finite),epoch=filter.epoch==='latest'?(epochs.length?Math.max(...epochs):null):filter.epoch;
 if(filter.time_mode!=='global'&&epoch!==null&&epoch!==''&&epoch!==undefined)query.set('epoch',epoch);
 for(const key of ['sample_id','task'])if(filter[key])query.set(key,filter[key]);
 if(filter.global_step!==undefined&&filter.global_step!=='')query.set('global_step',filter.global_step);
 else {const available=timeline.filter(item=>filter.time_mode==='global'||item.epoch===Number(epoch));if(available.length)query.set('global_step',available.at(-1).global_step);}
 return query;
}
async function refreshPredictionGallery(namespace,force=false,more=false){const container=document.querySelector(`#${namespace}-predictions`),id=galleryOwner(namespace);if(!container||!id)return;const key=`${namespace}:${id}`,previous=state.gallery[key];if(galleryRequests[key])return;if(!force&&!more&&previous&&Date.now()-previous.receivedAt<3000){if(container.dataset.loadedKey!==key)renderPredictionGallery(namespace,previous);return;}const request=new AbortController(),filterSignature=JSON.stringify(galleryFilters[namespace]);galleryRequests[key]=request;try{const query=galleryFilterQuery(namespace,previous?.data);if(more)query.set('offset',previous?.data.next_offset??previous?.data.entries?.length??0);const data=await api(`${galleryAPI(namespace,id)}?${query}`);if(galleryOwner(namespace)!==id||!document.querySelector(`#${namespace}-predictions`))return;const incoming=data.entries||[],keepHistory=!force&&!more&&previous?.filterSignature===filterSignature&&previous.data.entries?.length>incoming.length&&data.total>=previous.data.total,merged=more?[...(previous?.data.entries||[]),...incoming]:keepHistory?[...incoming,...(previous?.data.entries||[])]:incoming,unique=[...new Map(merged.map(entry=>[entry.id||JSON.stringify([entry.split,entry.epoch,entry.global_step,entry.sample_id,entry.task,entry.camera,entry.pred||entry.images?.pred]),entry])).values()];const nextOffset=keepHistory?Math.max(data.next_offset??0,previous.data.next_offset??0):data.next_offset;const record={id,data:{...data,entries:unique,...(nextOffset!==undefined?{next_offset:nextOffset,has_more:nextOffset<data.total}:{})},receivedAt:Date.now(),filterSignature};state.gallery[key]=record;if(filterSignature!==JSON.stringify(galleryFilters[namespace])){delete galleryRequests[key];await refreshPredictionGallery(namespace,true);return;}const filter=galleryFilters[namespace];if(!previous&&data.legacy&&!data.entries?.length){filter.split='';filter.epoch='';delete galleryRequests[key];await refreshPredictionGallery(namespace,true);return;}if(!previous&&filter.epoch==='latest'&&data.epochs?.length){delete galleryRequests[key];await refreshPredictionGallery(namespace,true);return;}renderPredictionGallery(namespace,record);}catch(error){if(container.isConnected)document.querySelector(`#${namespace}-prediction-entries`).innerHTML=`<div class="panel-body">${alertBox(esc(error.message),'error',translateStatic('Prediction 기록을 불러올 수 없습니다'))}</div>`;}finally{delete galleryRequests[key];}}
function gallerySelect(namespace,key,label,value,options){return `<label><span>${label}</span><select class="select-control" data-gallery-filter="${key}" data-gallery="${namespace}" aria-label="${label}">${options.map(([option,text])=>`<option value="${esc(option)}" ${String(value)===String(option)?'selected':''}>${esc(text)}</option>`).join('')}</select></label>`;}
function renderPredictionGallery(namespace,record){const container=document.querySelector(`#${namespace}-predictions`);if(!container)return;const {id,data}=record,filter=galleryFilters[namespace],entries=data.entries||[],fixed=filter.split==='val'?(data.fixed_samples||data.datasets?.val?.samples||[]):data.datasets?.train?.samples||[],samples=fixed.length?fixed:[...new Map(entries.filter(entry=>entry.sample_id).map(entry=>[entry.sample_id,{sample_id:entry.sample_id,relative_frame:entry.relative_frame}])).values()];const tasks=data.tasks||[],sample=filter.sample_id||samples[0]?.sample_id||entries[0]?.sample_id,task=filter.task||tasks[0]||entries[0]?.task;const toolbar=document.querySelector(`#${namespace}-prediction-filters`);toolbar.innerHTML=gallerySelect(namespace,'split',translateStatic('데이터 분할'),filter.split,[['val','VAL'],['train','TRAIN']])+gallerySelect(namespace,'task',translateStatic('태스크'),task,tasks.map(task=>[task,task]))+gallerySelect(namespace,'time_mode','시간축',filter.time_mode||'epoch',[['epoch','Epoch 내부 Step'],['global','전체 누적 Iteration']]);const datasetFingerprint=data.datasets?.[filter.split]?.dataset_fingerprint;document.querySelector(`#${namespace}-prediction-note`).innerHTML=`${filter.split==='val'?`<span>${translateStatic('고정 VAL 샘플')} <strong>${num(data.fixed_sample_count??data.fixed_samples?.length??data.datasets?.val?.count)}</strong> / 4</span>`:''}${datasetFingerprint?`<span title="${esc(datasetFingerprint)}">${translateStatic('데이터셋 ID')} <code>${esc(datasetFingerprint.slice(0,12))}</code></span>`:''}${data.storage_budget?.budget_exhausted?`<span class="warning-text">Prediction PNG 용량 한도 도달 · 기존 이미지 보존 · 학습 계속</span>`:''}${data.legacy?`<span>${translateStatic('기존 저장 이미지 · Epoch 정보가 없는 기록은 임의로 배정하지 않습니다.')}</span>`:''}`;document.querySelector(`#${namespace}-prediction-samples`).innerHTML=samples.map((item,index)=>`<button type="button" class="sample-tab ${sample===item.sample_id?'active':''}" data-action="prediction-sample" data-gallery="${namespace}" data-id="${esc(item.sample_id)}" title="${esc(item.relative_frame||item.sample_id)}">${say('샘플','Sample')} ${index+1}<small>${esc((item.relative_frame||item.sample_id).split('/').slice(-2).join('/'))}</small></button>`).join('');let current=entries.filter(entry=>(!sample||entry.sample_id===sample)&&(!task||entry.task===task));const cameras=[...new Set(current.map(e=>e.camera).filter(Boolean))];if(cameras.length>1){const camera=filter.camera||cameras[0];toolbar.innerHTML+=gallerySelect(namespace,'camera','Camera',camera,cameras.map(c=>[c,c]));current=current.filter(e=>e.camera===camera);}if(!data.legacy&&current.length){const step=filter.global_step!==undefined&&filter.global_step!==''?Number(filter.global_step):Math.max(...current.map(e=>e.global_step||0));current=current.filter(entry=>entry.global_step===step);}const body=document.querySelector(`#${namespace}-prediction-entries`),signature=JSON.stringify([id,filter,current.map(entry=>[entry.id,entry.capture_id,entry.epoch,entry.global_step,entry.images])]);if(body.dataset.signature!==signature){body.querySelectorAll('img').forEach(img=>predictionImageObserver?.unobserve(img));body.innerHTML=current.length?current.map(entry=>predictionEntryHTML(entry,namespace,id)).join(''):empty('camera',say('선택한 Epoch에 Prediction이 없습니다','No prediction for the selected epoch'),say('아직 기록하지 않았거나 저장 간격에 포함되지 않은 Epoch입니다.','This epoch has not been recorded or is outside the saved prediction interval.'));body.dataset.signature=signature;mountPredictionImages(body);}renderGalleryTimeline(namespace,record);document.querySelector(`#${namespace}-prediction-pagination`).innerHTML=data.legacy?`<div class="panel-foot">${say('Epoch를 알 수 없는 이전 기록','Legacy records without epoch metadata')}</div>`:'';container.dataset.loadedKey=`${namespace}:${id}`;if(namespace==='training')renderBestMetrics();}
function predictionEntryHTML(entry,namespace,id){const images=entry.images||entry,keys=[['input',translateStatic('입력')],['gt',translateStatic('정답')],['pred','Prediction']],urlBase=galleryAPI(namespace,id);return `<article class="prediction-entry" data-prediction-entry="${esc(entry.id||entry.sample_id||entry.pred)}"><header><div><strong>${esc(entry.task||translateStatic('기존 이미지'))}</strong><span>${entry.epoch!==null&&entry.epoch!==undefined?`Epoch ${num(entry.epoch)}`:translateStatic('Epoch 정보 없음')} ${entry.global_step!==null&&entry.global_step!==undefined?`· Global step ${num(entry.global_step)}${finite(entry.epoch_step)?` · Epoch step ${num(entry.epoch_step)}`:''}`:''} ${entry.camera?`· ${esc(entry.camera)}`:''}</span></div><span class="badge Idle">${esc((entry.split||'unknown').toUpperCase())}</span></header><p class="prediction-sample" title="${esc(entry.relative_frame||entry.sample_id||'')}">${esc(entry.relative_frame||entry.sample_id||entry.source||'')}</p><div class="prediction-triplet">${keys.filter(([key])=>images[key]).map(([key,label])=>`<figure><figcaption>${label}</figcaption><img loading="lazy" data-prediction-src="${esc(`${urlBase}/frame?path=${encodeURIComponent(images[key])}`)}" alt="${esc(`${label} · ${entry.task||''} · ${entry.relative_frame||entry.sample_id||''} · Epoch ${entry.epoch??'—'}`)}"><span class="prediction-image-error hide">${translateStatic('이미지를 불러올 수 없습니다')}</span></figure>`).join('')}</div>${entry.display_scale?`<footer>${translateStatic('표시 범위')} ${num(entry.display_scale.min)}–${num(entry.display_scale.max)} ${esc(entry.display_scale.unit||'')}</footer>`:''}</article>`;}
let predictionImageObserver=null;
function mountPredictionImages(root){if(!predictionImageObserver)predictionImageObserver=new IntersectionObserver(items=>{for(const item of items){if(!item.isIntersecting)continue;const img=item.target;predictionImageObserver.unobserve(img);const url=img.dataset.predictionSrc;delete img.dataset.predictionSrc;img.onerror=()=>{img.removeAttribute('src');img.nextElementSibling?.classList.remove('hide');};imageSource(img,url).catch(()=>img.onerror());img.onclick=()=>zoomImage(img);}},{rootMargin:'300px'});root.querySelectorAll('img[data-prediction-src]').forEach(img=>predictionImageObserver.observe(img));}
