async function loadPredictionComparison(experiments){const target=document.querySelector('#prediction-comparison');if(!target)return;try{const records=await Promise.all(experiments.map(async experiment=>({experiment,data:await api(`/api/experiments/${encodeURIComponent(experiment.id)}/predictions?split=val&limit=200`)})));if(!target.isConnected)return;const fingerprints=records.map(record=>record.data.dataset_fingerprint||record.data.datasets?.val?.dataset_fingerprint);if(!fingerprints.every(value=>value&&value===fingerprints[0])){target.innerHTML=panel(translateStatic('Prediction 비교'),`<div class="panel-body">${alertBox(translateStatic('동일한 VAL 데이터셋의 고정 샘플 기록이 있어야 Prediction을 비교할 수 있습니다. 각 실험의 결과 확인에서 개별 이미지를 볼 수 있습니다.'))}</div>`);return;}state.predictionCompareRecords=records;const samples=records[0].data.fixed_samples||[],commonSamples=samples.filter(sample=>records.every(record=>(record.data.fixed_samples||[]).some(value=>value.sample_id===sample.sample_id))),tasks=(records[0].data.tasks||[]).filter(task=>records.every(record=>(record.data.tasks||[]).includes(task)));target.innerHTML=panel(translateStatic('Prediction 비교'),`<div class="prediction-toolbar"><label><span>${translateStatic('고정 VAL 샘플')}</span><select id="prediction-compare-sample" class="select-control">${commonSamples.map((sample,index)=>`<option value="${esc(sample.sample_id)}">${index+1}. ${esc(sample.relative_frame||sample.sample_id)}</option>`).join('')}</select></label><label><span>${translateStatic('태스크')}</span><select id="prediction-compare-task" class="select-control">${tasks.map(task=>`<option>${esc(task)}</option>`).join('')}</select></label></div><div class="prediction-dataset-note">${translateStatic('같은 데이터셋·샘플·태스크를 비교합니다. 모델별 Epoch를 선택하세요.')}</div><div id="prediction-compare-entries" class="prediction-scroll"></div>`);renderPredictionComparison();}catch(error){if(target.isConnected)target.innerHTML=`<div class="panel-body">${alertBox(esc(error.message),'error')}</div>`;}}
async function renderPredictionComparison(){const target=document.querySelector('#prediction-compare-entries');if(!target)return;const records=state.predictionCompareRecords||[],sample=document.querySelector('#prediction-compare-sample')?.value,task=document.querySelector('#prediction-compare-task')?.value;if(!sample||!task){target.innerHTML=empty('camera',translateStatic('비교할 Prediction이 없습니다'),translateStatic('공통 샘플과 태스크가 있는 실험을 선택하세요.'));return;}target.innerHTML=records.map(({experiment,data})=>{const epochs=(data.epochs||[]).filter(finite).sort((a,b)=>b-a);return `<section class="prediction-model-compare" data-compare-prediction-model="${esc(experiment.id)}"><div class="prediction-model-title"><h3>${esc(experiment.name)}</h3><select class="select-control compact-select" data-prediction-model-epoch="${esc(experiment.id)}">${epochs.map(epoch=>`<option>${epoch}</option>`).join('')}</select></div><div id="prediction-compare-${esc(experiment.id)}"></div></section>`;}).join('');await Promise.all(records.map(record=>loadComparisonEntry(record.experiment.id)));}
async function loadComparisonEntry(id){const target=document.getElementById(`prediction-compare-${id}`);if(!target)return;const sample=document.querySelector('#prediction-compare-sample')?.value,task=document.querySelector('#prediction-compare-task')?.value,epoch=document.querySelector(`[data-prediction-model-epoch="${CSS.escape(id)}"]`)?.value,query=new URLSearchParams({split:'val',sample_id:sample||'',task:task||'',epoch:epoch||'',limit:'20'});try{const data=await api(`/api/experiments/${encodeURIComponent(id)}/predictions?${query}`);if(!target.isConnected)return;target.innerHTML=data.entries?.length?data.entries.map(entry=>predictionEntryHTML(entry,'result',id)).join(''):empty('camera',translateStatic('저장된 Prediction이 없습니다'),translateStatic('선택한 Epoch·샘플·태스크의 기록이 없습니다.'));mountPredictionImages(target);}catch(error){if(target.isConnected)target.innerHTML=alertBox(esc(error.message),'error');}}
document.addEventListener('change',event=>{const el=event.target;if(['prediction-compare-sample','prediction-compare-task'].includes(el.id))renderPredictionComparison();if(el.dataset.predictionModelEpoch)loadComparisonEntry(el.dataset.predictionModelEpoch);});

