async function deleteDataset(id,buttonEl){const record=state.datasets.find(d=>d.id===id);if(!record)return;const wasDisabled=buttonEl?.disabled;if(buttonEl)buttonEl.disabled=true;try{const target=await api(`/api/datasets/${encodeURIComponent(id)}/deletion`);if(!target.can_delete)throw new Error((target.blockers||[]).join(' '));const accepted=await confirmAction(say('데이터셋 삭제','Delete dataset'),say('이 Scene의 이미지·라벨·Metadata를 영구 삭제하시겠습니까? 삭제 후 복구할 수 없습니다.','Permanently delete this scene’s images, labels and metadata? This cannot be undone.'),say('확인','Confirm'),`<dl><div class="keyvalue"><dt>Scene</dt><dd>${esc(target.name)}</dd></div><div class="keyvalue"><dt>${say('경로','Path')}</dt><dd>${esc(target.path)}</dd></div><div class="keyvalue"><dt>${say('샘플','Samples')}</dt><dd>${num(record.samples)}</dd></div></dl>`,true);if(!accepted)return;await api(`/api/datasets/${encodeURIComponent(id)}`,'DELETE',{confirmation_name:target.name});await datasetDeleted(id);}finally{if(buttonEl?.isConnected)buttonEl.disabled=wasDisabled;}}
