 const sig=JSON.stringify([record.id,filter.time_mode,filter.split,filter.task,epochs,records]);
 if(target.dataset.epochSignature!==sig){galleryTimelines[namespace]?.destroy();galleryTimelines[`${namespace}-step`]?.destroy();target.innerHTML=(filter.time_mode!=='global'&&epochs.length?timelineHTML(`${namespace}-epoch`,{min:0,max:epochs.length-1,value:Math.max(0,epochs.indexOf(epoch)),label:'저장 Epoch',positions:epochs,note:`Epoch ${epoch??'—'} · 실제 기록된 Epoch만 표시`}):'')+`<div id="${namespace}-step-timeline"></div>`;target.dataset.epochSignature=sig;if(filter.time_mode!=='global'&&epochs.length)galleryTimelines[namespace]=mountTimeline(target.querySelector('[data-timeline]'),async index=>{filter.epoch=epochs[index];filter.global_step='';await refreshPredictionGallery(namespace,true);});}
 const stepTarget=document.querySelector(`#${namespace}-step-timeline`),index=Math.max(0,selected),item=records[index],note=item?`Epoch ${item.epoch} · ${finite(item.epoch_step)?`Epoch step ${item.epoch_step}`:'Epoch step 기록 없음 (기존 기록)'} · Global step ${item.global_step}`:'실제 저장된 Step이 없습니다';
