let taskCatalogRequest=0,taskCatalogSignature='';
function colorCSS(value){return Array.isArray(value)?`rgb(${value.slice(0,3).map(Number).join(',')})`:/^#[\da-f]{6}$/i.test(value||'')?value:'#61758e';}
function advancedSettingsShell(){return `<section class="panel" data-training-stage="advanced"><div class="panel-head"><div><h2>${say('태스크 고급 설정','Advanced task settings')}</h2><p>${say('실제 라벨에서 발견한 클래스와 단위를 사용합니다. 새 작업의 설정에만 적용됩니다.','Uses classes and units discovered in actual labels. Changes apply only to new jobs.')}</p></div>${button(say('클래스 다시 확인','Refresh classes'),'refresh-task-catalog','subtle small','refresh')}</div><div id="task-advanced-settings"><p class="task-catalog-note">${say('데이터셋의 클래스와 인코딩을 확인하고 있습니다.','Inspecting dataset classes and encodings.')}</p></div></section>`;}
async function refreshTaskCatalog(force=false){const target=document.querySelector('#task-advanced-settings');if(!target)return;const {task_settings,...draft}=trainingOptionsDraft(),signature=JSON.stringify(draft);if(!force&&state.taskCatalog&&taskCatalogSignature===signature){if(!target.dataset.loaded)renderTaskAdvanced();return;}const request=++taskCatalogRequest;try{const catalog=await api('/api/training/task-catalog','POST',draft);if(request!==taskCatalogRequest||!document.querySelector('#task-advanced-settings'))return;state.taskCatalog=catalog;taskCatalogSignature=signature;if(!state.taskDraftSettings)state.taskDraftSettings=structuredClone(state.training.task_settings||catalog.recommended_task_settings||{});renderTaskAdvanced();await refreshTrainingOptions();}catch(error){if(request===taskCatalogRequest&&target.isConnected)target.innerHTML=`<p class="task-catalog-note error-text">${esc(error.message)}</p>`;}}
function renderTaskAdvanced(){const target=document.querySelector('#task-advanced-settings');if(!target)return;const c=state.taskCatalog||{},settings=state.taskDraftSettings||state.training.task_settings||c.recommended_task_settings||{},seg=settings.segmentation||{},depth=settings.depth||{},od=settings.detection||{},bev=settings.bev||{};const classChecks=(key,classes,selected=[],supportedOnly=false)=>classes.length?`<div class="advanced-class-list">${classes.map(item=>`<label class="advanced-class-option" title="${esc(item.name)} · ID ${esc(item.id)}"><input type="checkbox" name="advanced_${key}_${esc(item.id)}" value="${esc(item.id)}" ${selected.includes(item.id)?'checked':''} ${supportedOnly&&(item.available===false||item.trainable===false)?'disabled':''}><i style="background:${colorCSS(item.color)}"></i><span>${esc(item.name||item.label||item.id)}</span><small>${key==='seg'?`ID ${item.id} · TRAIN ${num(item.train_pixels||0)} / VAL ${num(item.val_pixels||0)}${!item.train_pixels&&item.val_pixels?' · VAL only':''}`:item.trainable===false?say('표시 전용','View only'):num(item.pixels??item.boxes)}</small></label>`).join('')}</div>`:`<p class="dependency-hint">${say('실제 데이터에서 발견된 클래스가 없습니다.','No classes found in the actual data.')}</p>`;target.innerHTML=`<details class="task-advanced" data-task-advanced="seg"><summary>Segmentation · ${say('고급 설정','Advanced settings')}</summary><div class="form-section"><div class="form-grid">${field('advanced_seg_mode',say('라벨 매핑','Label mapping'),seg.mode||'carla',{options:[['carla',say('CARLA 원본 클래스','CARLA source classes')],['legacy',say('기존 6채널 호환 모드','Legacy six-channel compatibility')]]})}${field('advanced_seg_excluded',say('제외한 클래스 처리','Excluded classes'),seg.excluded||'ignore',{options:[['ignore','Ignore index · 255'],['background',say('Background로 통합','Merge into Background')]]})}</div><p class="task-scheme-note">${say('CARLA 모드는 선택한 실제 ID 순서로 Head·Loss·Metric·팔레트를 함께 구성합니다. 기존 6채널 모드는 이전 Checkpoint 재현용입니다.','CARLA mode aligns selected source IDs across the head, loss, metrics and palette. Legacy mode reproduces existing six-channel checkpoints.')}</p>${classChecks('seg',c.segmentation?.classes||[],seg.class_ids||[])}<div class="inline-actions spaced">${button('TRAIN 관측 클래스만 적용','train-observed-classes','subtle small')}</div><p class="dependency-hint">TRAIN에 없는 선택 클래스는 준비 상태 검사에서 차단합니다. 자동 해제하거나 VAL을 학습에 합치지 않습니다.</p><p class="dependency-hint spaced">${esc(c.segmentation?.encoding||'')}</p></div></details><details class="task-advanced" data-task-advanced="depth"><summary>Depth · ${say('고급 설정','Advanced settings')}</summary><div class="form-section"><div class="form-grid three">${field('advanced_depth_min_m','Minimum depth',depth.min_m??.001,{type:'number',min:0,max:1000,step:'any',unit:'m'})}${field('advanced_depth_max_m','Maximum depth',depth.max_m??100,{type:'number',min:0,max:1000,step:'any',unit:'m'})}${field('advanced_depth_out_of_range',say('학습 범위 밖의 값','Outside training range'),depth.out_of_range||'mask',{options:[['mask','Mask'],['clip','Clip']]})}${field('advanced_depth_invalid','Invalid depth','mask',{options:[['mask',say('Mask · Loss와 Metric에서 제외','Mask · Excluded from loss and metrics')]],readonly:true})}${field('advanced_depth_visual_min_m',say('시각화 최소 거리','Display minimum'),depth.visual_min_m??0,{type:'number',min:0,max:1000,step:'any',unit:'m'})}${field('advanced_depth_visual_max_m',say('시각화 최대 거리','Display maximum'),depth.visual_max_m??100,{type:'number',min:0,max:1000,step:'any',unit:'m'})}${field('advanced_depth_colormap','Color map',depth.colormap||'plasma',{options:['plasma','viridis','turbo','gray']})}${field('advanced_depth_encoding',say('원본 인코딩','Source encoding'),depth.encoding||'auto',{options:[['auto',say('데이터 Provenance에서 자동 확인','Automatic from data provenance')],['meters_f32','Float32 · meters'],['meters_u8','UInt8 · meters'],['legacy_100m_u8','Legacy UInt8 · 100/255 m']]})}</div><p class="task-scheme-note">${say('학습 거리와 표시 거리는 별도입니다. 손실된 정밀도와 포화 픽셀은 복원하지 않습니다.','Training and display ranges are independent. Lost precision and saturated pixels cannot be recovered.')}</p>${(c.depth?.warnings||[]).map(message=>`<p class="dependency-hint warning-text">${esc(message)}</p>`).join('')}</div></details><details class="task-advanced" data-task-advanced="od"><summary>Object Detection · ${say('고급 설정','Advanced settings')}</summary><div class="form-section">${classChecks('od',c.detection?.classes||[],od.class_ids||[])}<p class="task-scheme-note">${esc(c.detection?.format||'')} · ${num(c.detection?.annotation_count??0)} ${say('개 실제 Box','actual boxes')}</p>${!(c.detection?.classes||[]).length?`<p class="prerequisite-text">${say('Bounding Box 파일이 존재해도 양성 객체 라벨이 없으면 검출 클래스를 선택할 수 없습니다.','Box files exist, but no positive object labels are available to select.')}</p>`:''}</div></details><details class="task-advanced" data-task-advanced="bev"><summary>BEV · ${say('고급 설정','Advanced settings')}</summary><div class="form-section"><h3>${say('학습 Semantic / Map Layer','Training semantic / map layers')}</h3>${classChecks('bev',c.bev?.layers||[],bev.layers||[],true)}<h3 class="spaced">${say('시각화 레이어','Visualization layers')}</h3><div class="check-grid">${(c.bev?.layers||[]).map(layer=>check(`advanced_bev_visual_${layer.id}`,esc(layer.name||layer.id),bev.visual_layers?.includes(layer.id),layer.available===false?'disabled':'')).join('')}</div><p class="task-scheme-note">${say('Route·Traffic Light·Stop Line은 학습 Semantic Head와 구분한 표시 레이어입니다. 기하학적 범위는 수집 당시 보정 정보를 사용합니다.','Route, traffic light and stop line are display layers separate from semantic training heads. Geometry uses the calibration recorded at collection.')}</p><dl>${Object.entries(c.bev?.geometry||{}).map(([key,value])=>`<div class="keyvalue"><dt>${esc(key)}</dt><dd>${esc(typeof value==='object'?JSON.stringify(value):value??'N/A')}</dd></div>`).join('')}</dl>${[3,4].includes(c.bev?.schema_version)?`<p class="task-scheme-note">${c.bev?.schema_version===4?say('Global PNG에는 픽셀별 도로 높이가 없어 N/A입니다. 실제 Actor의 높이는 별도 Ground Truth 채널입니다. 기존 2D BEV 입력 채널은 유지합니다.','Global PNGs have no per-pixel road elevation: N/A. Recorded actor heights are separate ground-truth channels. Existing 2D BEV inputs remain unchanged.'):say('높이 값은 미터 단위 Ground Truth 채널로 별도 로드합니다. 기존 2D BEV 모델의 입력 채널을 자동 변경하지 않습니다.','Heights load as separate ground-truth channels in meters. Existing 2D BEV model input channels remain unchanged.')}</p><dl><div class="keyvalue"><dt>Height channels</dt><dd>${esc((c.bev.height_channels||[]).join(', ')||'N/A')}</dd></div></dl><div class="layer-controls">${(c.bev.semantic_classes||[]).map(item=>`<span class="layer-toggle"><i style="background:${colorCSS(item.color)}"></i>${esc(item.name)} <small>ID ${esc(item.id)}</small></span>`).join('')}</div>`:''}</div></details>${(c.warnings||[]).length?`<details class="task-advanced"><summary>${say('데이터 검사 참고 사항','Dataset inspection notes')}</summary><div class="form-section">${c.warnings.map(w=>`<p class="dependency-hint">${esc(w)}</p>`).join('')}</div></details>`:''}`;target.dataset.loaded='1';if(!(c.detection?.classes||[]).length){const checkbox=document.querySelector('[name=task_od]');if(checkbox){checkbox.checked=false;checkbox.disabled=true;checkbox.closest('label')?.classList.add('unavailable');checkbox.closest('label')?.setAttribute('title',say('실제 데이터에 양성 Bounding Box가 없습니다.','No positive bounding boxes in the dataset.'));}}}
function readAdvancedSettings(){const base=structuredClone(state.taskDraftSettings||state.training.task_settings||state.taskCatalog?.recommended_task_settings||{}),form=document.querySelector('#training-form');if(!form?.querySelector('[name=advanced_seg_mode]'))return base;const d=new FormData(form),catalog=state.taskCatalog||{};base.segmentation={mode:d.get('advanced_seg_mode'),class_ids:(catalog.segmentation?.classes||[]).filter(c=>d.has(`advanced_seg_${c.id}`)).map(c=>c.id),excluded:d.get('advanced_seg_excluded')};base.depth={...(base.depth||{}),encoding:d.get('advanced_depth_encoding'),invalid:'mask',out_of_range:d.get('advanced_depth_out_of_range'),colormap:d.get('advanced_depth_colormap')};for(const key of ['min_m','max_m','visual_min_m','visual_max_m'])base.depth[key]=Number(d.get(`advanced_depth_${key}`));base.detection={class_ids:(catalog.detection?.classes||[]).filter(c=>d.has(`advanced_od_${c.id}`)).map(c=>c.id)};base.bev={layers:(catalog.bev?.layers||[]).filter(c=>c.trainable!==false&&d.has(`advanced_bev_${c.id}`)).map(c=>c.id),visual_layers:(catalog.bev?.layers||[]).filter(c=>d.has(`advanced_bev_visual_${c.id}`)).map(c=>c.id)};return base;}
actions['refresh-task-catalog']=()=>refreshTaskCatalog(true);
document.addEventListener('change',event=>{const name=event.target.name||'';if(name.startsWith('advanced_')){state.taskDraftSettings=readAdvancedSettings();refreshTrainingOptions();}if(['train_data','val_data'].includes(name)||name.startsWith('sensor_'))refreshTaskCatalog(true);});

let liveSceneJob='',liveScenePending=false,liveSceneFetchedAt=0,liveSceneAbort=null,liveSceneRequest=0;
async function refreshLiveScene(){const target=document.querySelector('#sensor-preview'),information=document.querySelector('#collection-scene-info'),job=latest('collection');if(!target||!information||!job||!collectionPreviewEnabled()||liveScenePending)return false;const id=job.id,channel=document.querySelector('#preview-mode')?.value||'camera',layerSignature=JSON.stringify([state.liveLayers,state.liveBevView]),request=++liveSceneRequest;let response=liveSceneJob===id?state.liveFrame:null;const oldKey=response?JSON.stringify([id,response.dataset_id,response.index,channel,layerSignature]):'';if(response&&Date.now()-liveSceneFetchedAt<3000&&target.dataset.bundleKey===oldKey)return false;liveScenePending=true;liveSceneAbort?.abort();liveSceneAbort=new AbortController();const signal=liveSceneAbort.signal;try{if(!response||Date.now()-liveSceneFetchedAt>=3000){response=await api(`/api/jobs/${encodeURIComponent(id)}/scene`,'GET',undefined,{signal});liveSceneFetchedAt=Date.now();}if(!response.scene||!response.dataset_id||!finite(response.index)){if(target.isConnected){target.innerHTML=empty('camera',say('저장된 Frame 대기 중','Waiting for a saved frame'),say('센서와 Metadata가 함께 저장된 Frame부터 표시합니다.','Frames appear after sensors and metadata are committed together.'));information.innerHTML=sceneInformationHTML({},'live');}return false;}const layers=state.liveFrame?.dataset_id===response.dataset_id&&state.liveLayers!==undefined?state.liveLayers:response.bev_gt?defaultBevOverlays(response.bev_gt):(response.layers||[]).filter(layer=>layer.available!==false).map(layer=>layer.id),query=new URLSearchParams({index:String(response.index),channel:channel==='bev'?(state.liveBevView||'bev'):'rgb',camera:response.camera||'front_cam'});if(channel==='bev'&&layers!==null)query.set('layers',layers.join(','));const img=new Image();img.alt=`${channel==='bev'?'BEV':'RGB'} · ${say('저장 Frame','Saved frame')} ${response.frame_key??response.index}`;img.dataset.frameIndex=String(response.index);await imageSource(img,`/api/datasets/${encodeURIComponent(response.dataset_id)}/frame?${query}`,{signal});if(img.src)await img.decode();if(!img.naturalWidth||!target.isConnected||!information.isConnected||request!==liveSceneRequest||latest('collection')?.id!==id||!collectionPreviewEnabled()||(document.querySelector('#preview-mode')?.value||'camera')!==channel||layerSignature!==JSON.stringify([state.liveLayers,state.liveBevView]))return false;state.liveScene=response.scene;state.liveFrame=response;liveSceneJob=id;const stage=document.createElement('div');stage.className='preview-stage';const chip=document.createElement('span');chip.className='preview-chip';chip.textContent=`${say('최근 저장 Frame','Latest saved frame')} · ${response.frame_key??response.index}`;stage.append(chip,img);img.onclick=()=>zoomImage(img);target.replaceChildren(stage);information.innerHTML=sceneInformationHTML(state.liveScene,'live');for(const element of [target,information]){element.dataset.frameIndex=String(response.index);element.dataset.datasetId=response.dataset_id;}renderLiveLayers();const legend=document.querySelector('#collection-bev-legend');if(legend)legend.innerHTML=channel==='bev'?bevLegend(response.bev_gt,state.liveBevView||'bev'):'';target.dataset.bundleKey=JSON.stringify([id,response.dataset_id,response.index,channel,JSON.stringify([state.liveLayers,state.liveBevView])]);const caption=document.querySelector('#preview-caption');if(caption)caption.textContent=`${say('센서·차량 정보가 동일한 저장 Frame입니다. 최대 3초 간격으로 확인합니다.','Sensors and vehicle state refer to the same saved frame. Checked every 3 seconds.')} · ${response.frame_key??response.index} · Timestamp ${finite(response.timestamp)?response.timestamp.toFixed(3):'N/A'} s`;return true;}catch(error){if(error.name!=='AbortError'&&target.isConnected&&!target.querySelector('img')){target.innerHTML=empty('camera',say('저장 프레임을 확인할 수 없습니다','Saved frame unavailable'),esc(error.message));information.innerHTML=sceneInformationHTML({},'live');}return false;}finally{liveScenePending=false;}}

function renderLiveLayers(){const target=document.querySelector('#collection-live-layers'),layers=state.liveFrame?.layers?.filter(layer=>layer.available!==false)||[];if(!target||!layers.length)return;const signature=JSON.stringify([state.liveFrame.dataset_id,layers.map(layer=>layer.id)]);if(target.dataset.signature===signature)return;state.liveLayers=state.liveFrame.bev_gt?defaultBevOverlays(state.liveFrame.bev_gt):layers.map(layer=>layer.id);state.liveBevView='bev';target.innerHTML=`<div class="bev-view-toolbar"><label>${say('BEV 보기','BEV view')}<select id="live-bev-view">${bevViewOptions(state.liveFrame.bev_views)}</select></label></div><details class="live-bev-layers"><summary>${say('BEV 레이어 표시','BEV display layers')}</summary><div class="layer-controls">${layers.map(layer=>`<label class="layer-toggle"><input type="checkbox" data-live-bev-layer="${esc(layer.id)}" ${state.liveLayers===null||state.liveLayers.includes(layer.id)?'checked':''}><i style="background:${colorCSS(layer.color)}"></i>${esc(layer.label||layer.name||layer.id)}</label>`).join('')}</div></details>`;target.dataset.signature=signature;target.onchange=event=>{if(event.target.id==='live-bev-view'){state.liveBevView=event.target.value;const mode=document.querySelector('#preview-mode');if(mode)mode.value='bev';}else state.liveLayers=[...target.querySelectorAll('[data-live-bev-layer]:checked')].map(el=>el.dataset.liveBevLayer);refreshPreview();};}

function renderEpochMetricStrip(){const node=document.querySelector('#training-epoch-metrics');if(!node)return;const series=metricsFromJob(latest('training')).filter(item=>item.split==='val'&&(item.x_label||'epoch')==='epoch'&&!metricInfo(item).detail),epoch=selectedMonitorEpoch();const priority=name=>/^(seg_miou|seg_mdice|seg_mean_dice|seg_pixel_accuracy|depth_abs_rel|depth_rmse|od_map50|od_map_50|val_loss|loss)$/i.test(name)?0:1;const selected=series.sort((a,b)=>priority(a.name)-priority(b.name)).slice(0,6);node.innerHTML=selected.map(row=>{const point=epoch===null?row.points.at(-1):row.points.find(p=>p.x===epoch),info=metricInfo(row);return `<div><span>${esc(info.label)}</span><strong>${metricValue(point?.y)}</strong></div>`;}).join('');}

function navigate(path){if(location.hash===`#${path}`)render();else location.hash=path;}
function applyRoute(){const parts=location.hash.slice(1).split('/');state.route=Object.hasOwn(routes,parts[0])?parts[0]:'dashboard';if(state.route==='simulation'){if(['collect','sensors','datasets','recorded'].includes(parts[1]))state.simTab=parts[1];if(parts[2])state.previewId=decodeURIComponent(parts[2]);}if(state.route==='training'){if(['setup','monitor','queue'].includes(parts[1]))state.trainTab=parts[1];if(parts[1]==='monitor'&&parts[2])state.monitorJob=decodeURIComponent(parts[2]);}if(state.route==='results'&&parts[1]&&state.detail?.id!==decodeURIComponent(parts[1])){const id=decodeURIComponent(parts[1]);api(`/api/experiments/${encodeURIComponent(id)}`).then(detail=>{if(location.hash.slice(1)==='results/'+encodeURIComponent(id)){state.detail=detail;renderDetail();}}).catch(error=>toast(error.message,true));}try{sessionStorage.setItem('sdv-subroutes',JSON.stringify({simTab:state.simTab,trainTab:state.trainTab}));}catch{}}
function stoppedTrainingActions(job,small=false){if(job.kind!=='training'||!['Stopped','Failed','Completed','Paused'].includes(job.status))return '';return `${job.can_resume?button(`Checkpoint 이어하기 · Epoch ${(job.last_completed_epoch||0)+1}`,'resume-job',`primary ${small?'small':''}`,'play',`data-id="${esc(job.id)}"`):''}${button('새 학습 · Epoch 1부터','restart-job',`subtle ${small?'small':''}`,'refresh',`data-id="${esc(job.id)}"`)}`;}
async function restartTraining(id){if(!await confirmAction('Epoch 1부터 새 학습을 시작할까요?','이 작업의 저장된 설정과 데이터 경로로 새 실험을 만듭니다. 이전 결과·체크포인트는 보존합니다.','새 학습 시작'))return;const result=await api(`/api/jobs/${encodeURIComponent(id)}/restart`,'POST');state.jobs=[result,...state.jobs.filter(job=>job.id!==result.id)];state.monitorJob=result.id;await refreshQueue();navigate(`training/monitor/${result.id}`);toast('새 실험을 대기열에 추가했습니다. Epoch 1부터 시작합니다.');}
actions['restart-job']=el=>restartTraining(el.dataset.id);
actions['train-observed-classes']=async()=>{const classes=state.taskCatalog?.segmentation?.classes||[],ids=classes.filter(item=>item.train_pixels>0).map(item=>item.id),current=readAdvancedSettings(),removed=(current.segmentation?.class_ids||[]).filter(id=>!ids.includes(id));if(!ids.length)throw new Error('TRAIN에서 확인된 클래스가 없습니다.');if(!await confirmAction('TRAIN에서 관측한 클래스만 적용할까요?',`TRAIN에 없는 선택 클래스 [${removed.join(', ')}]를 제외하고 실제 TRAIN 클래스 ${ids.length}개를 선택합니다. VAL 데이터는 합치지 않습니다. 제외 픽셀은 현재 Ignore/Background 설정을 따릅니다.`,'선택 적용'))return;current.segmentation={...current.segmentation,class_ids:ids};state.taskDraftSettings=current;renderTaskAdvanced();state.trainingDirty=true;captureDrafts();await refreshTrainingOptions();};
document.addEventListener('change',event=>{if(event.target.name?.startsWith('loss_')||event.target.name?.startsWith('task_'))syncLossSettings();});
